static int lm_trans_registry_descriptor_payload_is_numeric(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *payload) {
    (void)lm_lmx_message_thread;
    const char *codec;
    if (payload == 0) {
        return 0;
    }
    if (lm_trans_text_equals(lm_lmx_message_thread, payload, "int") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "size_t") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "int8") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "uint8") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "categoryFlag") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "decimal") != 0 || lm_trans_text_equals(lm_lmx_message_thread, payload, "serial") != 0) {
        return 1;
    }
    codec = lm_trans_registry_serialization_codec_value(lm_lmx_message_thread, payload);
    if (codec != 0 && strcmp(codec, "lmx.decimal-atom") == 0) {
        return 1;
    }
    return 0;
}

static int lm_trans_registry_text_is_numeric_atom(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *text) {
    (void)lm_lmx_message_thread;
    size_t i;
    int saw_digit;
    int saw_dot;
    char ch;
    if (text == 0 || text -> data == 0 || text -> length == 0U) {
        return 0;
    }
    i = 0U;
    if (text -> data[i] == '-' || text -> data[i] == '+') {
        i = i + 1U;
    }
    if (i >= text -> length) {
        return 0;
    }
    saw_digit = 0;
    saw_dot = 0;
    while (i < text -> length) {
        ch = text -> data[i];
        if (ch >= '0' && ch <= '9') {
            saw_digit = 1;
            i = i + 1U;
            continue;
        }
        if (ch == '.' && saw_dot == 0) {
            saw_dot = 1;
            i = i + 1U;
            continue;
        }
        break;
    }
    if (saw_digit == 0) {
        return 0;
    }
    while (i < text -> length) {
        ch = text -> data[i];
        if (ch != 'u' && ch != 'U' && ch != 'l' && ch != 'L' && ch != 'f' && ch != 'F') {
            return 0;
        }
        i = i + 1U;
    }
    return 1;
}

