static int lm_trans_array_head_find_close(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *text, size_t open_index, size_t *out_close_index) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t depth;
    char quote;
    if (text == 0 || out_close_index == 0 || open_index >= text -> length || text -> data[open_index] != '[') {
        return 0;
    }
    i = open_index;
    depth = 0U;
    while (i < text -> length) {
        if (text -> data[i] == '"' || text -> data[i] == '`') {
            quote = text -> data[i];
            i = i + 1U;
            while (i < text -> length) {
                if (quote == '"' && text -> data[i] == '\\') {
                    i = i + 2U;
                    continue;
                }
                if (quote == '`' && text -> data[i] == '`' && i + 1U < text -> length && text -> data[i + 1U] == '`') {
                    i = i + 2U;
                    continue;
                }
                if (text -> data[i] == quote) {
                    i = i + 1U;
                    break;
                }
                i = i + 1U;
            }
            continue;
        }
        if (text -> data[i] == '\'') {
            i = i + 1U;
            while (i < text -> length) {
                if (text -> data[i] == '\\') {
                    i = i + 2U;
                    continue;
                }
                if (text -> data[i] == '\'') {
                    i = i + 1U;
                    break;
                }
                i = i + 1U;
            }
            continue;
        }
        if (text -> data[i] == '[') {
            depth = depth + 1U;
        }
        else {
            if (text -> data[i] == ']') {
                depth = depth - 1U;
                if (depth == 0U) {
                    out_close_index[0] = i;
                    return 1;
                }
            }
        }
        i = i + 1U;
    }
    return 0;
}

static int lm_trans_array_head_next_dimension(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *head, size_t *index, LmP0Text *out_dimension) {
    (void)lm_lmx_message_thread;
    size_t close_index;
    if (head == 0 || index == 0 || out_dimension == 0 || index[0] >= head -> length || head -> data[index[0]] != '[') {
        return 0;
    }
    if (lm_trans_array_head_find_close(lm_lmx_message_thread, head, index[0], &close_index) == 0) {
        return 0;
    }
    out_dimension->data = head -> data + index[0] + 1U;
    out_dimension->length = close_index - index[0] - 1U;
    index[0] = close_index + 1U;
    return 1;
}

static int lm_trans_text_is_array_receiver_head(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *head) {
    (void)lm_lmx_message_thread;
    size_t index;
    size_t count;
    LmP0Text * dimension;
    index = 0U;
    count = 0U;
    if (head == 0) {
        return 0;
    }
    dimension = lm_trans_text_ref_new_cstr("");
    if (dimension == 0) {
        return 0;
    }
    while (index < head -> length) {
        if (lm_trans_array_head_next_dimension(lm_lmx_message_thread, head, &index, dimension) == 0) {
            lm_trans_text_ref_destroy(&dimension);
            return 0;
        }
        count = count + 1U;
    }
    lm_trans_text_ref_destroy(&dimension);
    return count > 0U;
}

