static int lm_trans_function_header_copy(struct LmMessageThread *lm_lmx_message_thread, LmTransFunctionHeader *target, const LmTransFunctionHeader *source) {
    (void)lm_lmx_message_thread;
    LmP0Text * name;
    LmP0Text * c_name;
    LmP0Text * env_type_name;
    LmTransFormalParamList * params;
    if (target == 0 || source == 0 || lm_trans_function_header_init_fields(lm_lmx_message_thread, target) != 0) {
        return 1;
    }
    params = 0;
    if (source -> params != 0) {
        params = lm_trans_formal_param_list_from_node(lm_lmx_message_thread, source -> params_node, source -> is_descriptor_only || source -> is_callable_descriptor, "function parameters");
        if (params == 0) {
            return 1;
        }
    }
    lm_trans_formal_param_list_delete(lm_lmx_message_thread, target -> params);
    target->params = 0;
    name = target -> name;
    c_name = target -> c_name;
    env_type_name = target -> env_type_name;
    target[0] = source[0];
    target->name = name;
    target->c_name = c_name;
    target->env_type_name = env_type_name;
    target->params = params;
    if (source -> name != 0) {
        target->name[0] = source -> name[0];
    }
    else {
        target->name->data = "";
        target->name->length = 0U;
    }
    if (source -> c_name != 0) {
        target->c_name[0] = source -> c_name[0];
    }
    else {
        target->c_name->data = "";
        target->c_name->length = 0U;
    }
    if (source -> env_type_name != 0) {
        target->env_type_name[0] = source -> env_type_name[0];
    }
    else {
        target->env_type_name->data = "";
        target->env_type_name->length = 0U;
    }
    return 0;
}

