    card = lm_trans_identifier_table_find_card(lm_lmx_message_thread, table, name);
    if (card != 0) {
        lm_trans_text_ref_destroy(&payload);
        return card;
    }
    hash = lm_trans_hash_bytes(lm_lmx_message_thread, payload -> data, payload -> length);
    bucket = hash % table -> bucket_count;
    card = lm_own_new_zero(sizeof(card[0]));
    if (card == 0) {
        lm_trans_text_ref_destroy(&payload);
        return 0;
    }
    copy = lm_trans_text_copy_cstr(lm_lmx_message_thread, payload);
    if (copy == 0) {
        lm_trans_text_ref_destroy(&payload);
        lm_trans_identifier_card_destroy(lm_lmx_message_thread, card);
        return 0;
    }
    card->name_storage = copy;
    card->name = lm_trans_text_ref_new_cstr(copy);
    if (card -> name == 0) {
        lm_trans_text_ref_destroy(&payload);
        lm_trans_identifier_card_destroy(lm_lmx_message_thread, card);
        return 0;
    }
    card->symbols = lm_trans_ptr_stack_new(lm_lmx_message_thread, 0);
    if (card -> symbols == 0) {
        lm_trans_text_ref_destroy(&payload);
        lm_trans_identifier_card_destroy(lm_lmx_message_thread, card);
        return 0;
    }
    card->relation_bucket_count = 31U;
    card->relation_buckets = lm_own_new_zero(card -> relation_bucket_count * sizeof(card -> relation_buckets[0]));
