static int lm_trans_capture_init_fields(struct LmMessageThread *lm_lmx_message_thread, LmTransCapture *capture) {
    (void)lm_lmx_message_thread;
    if (capture == 0) {
        return 1;
    }
    if (capture -> name == 0) {
        capture->name = lm_trans_text_ref_new_cstr("");
    }
    if (capture -> type_head == 0) {
        capture->type_head = lm_trans_text_ref_new_cstr("");
    }
    return capture -> name == 0 || capture -> type_head == 0;
}

static int lm_trans_capture_reset(struct LmMessageThread *lm_lmx_message_thread, LmTransCapture *capture) {
    (void)lm_lmx_message_thread;
    if (lm_trans_capture_init_fields(lm_lmx_message_thread, capture) != 0) {
        return 1;
    }
    capture->name->data = "";
    capture->name->length = 0U;
    capture->type_head->data = "";
    capture->type_head->length = 0U;
    capture->type_node = 0;
    capture->pointer_depth = 0U;
    capture->type_is_head = 0;
    return 0;
}

static LmTransCapture * lm_trans_capture_new(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *name, const LmP0Text *type_head, const LmP0Node *type_node, size_t pointer_depth, int type_is_head) {
    (void)lm_lmx_message_thread;
    LmTransCapture * capture;
    if (name == 0 || type_head == 0) {
        return 0;
    }
    capture = lm_own_new_zero(sizeof(capture[0]));
    if (capture != 0) {
        if (lm_trans_capture_init_fields(lm_lmx_message_thread, capture) != 0) {
            lm_trans_text_ref_destroy(&capture -> name);
            lm_trans_text_ref_destroy(&capture -> type_head);
            lm_own_delete(capture, 0);
            return 0;
        }
        capture->name[0] = name[0];
        capture->type_head[0] = type_head[0];
        capture->type_node = type_node;
        capture->pointer_depth = pointer_depth;
        capture->type_is_head = type_is_head;
    }
    return capture;
}

static void lm_trans_capture_destroy(struct LmMessageThread *lm_lmx_message_thread, LmTransCapture *capture) {
    (void)lm_lmx_message_thread;
    if (capture != 0) {
        lm_trans_text_ref_destroy(&capture -> name);
        lm_trans_text_ref_destroy(&capture -> type_head);
    }
    lm_own_delete(capture, 0);
}

