static char * lm_trans_callable_adapter_name_new(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *source_name, const LmP0Text *descriptor_name) {
    (void)lm_lmx_message_thread;
    const char *prefix;
    const char *middle;
    size_t prefix_length;
    size_t middle_length;
    size_t length;
    size_t i;
    size_t out;
    char *name;
    prefix = "lm_trans_adapter_";
    middle = "_as_";
    prefix_length = strlen(prefix);
    middle_length = strlen(middle);
    if ((source_name == 0) || (descriptor_name == 0)) {
        return 0;
    }
    length = (((prefix_length + source_name -> length) + middle_length) + descriptor_name -> length);
    name = (((char *)lm_own_new_zero(length + 1U)));
    if (name == 0) {
        return 0;
    }
    memcpy(name, prefix, prefix_length);
    out = prefix_length;
    i = 0U;
    while (i < source_name -> length) {
        if (lm_trans_c_identifier_char(lm_lmx_message_thread, source_name -> data[i])) {
            name[out] = source_name -> data[i];
            out = out + 1U;
        }
        else {
            name[out] = '_';
            out = out + 1U;
        }
        i = i + 1U;
    }
    memcpy((name + out), middle, middle_length);
    out = out + middle_length;
    i = 0U;
    while (i < descriptor_name -> length) {
        if (lm_trans_c_identifier_char(lm_lmx_message_thread, descriptor_name -> data[i])) {
            name[out] = descriptor_name -> data[i];
            out = out + 1U;
        }
        else {
            name[out] = '_';
            out = out + 1U;
        }
        i = i + 1U;
    }
    name[out] = '\0';
    return name;
}

