static int lm_trans_emit_callable_default_adapter_bound_args(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransNamespace *namespace_, const LmP0Structure *body, const LmTransSymbol *source_symbol, size_t bound_count, LmTransAbiParam **descriptor_params, size_t descriptor_param_count) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Field * next;
    const LmP0Field * default_first;
    const LmP0Node * param_node;
    size_t index;
    int wrote;
    field = lm_trans_call_body_first_field(lm_lmx_message_thread, body);
    wrote = 0;
    index = 0U;
    while (index < bound_count) {
        param_node = lm_trans_callable_param_node_at(lm_lmx_message_thread, source_symbol, index);
        if (param_node == 0) {
            return 1;
        }
        if (wrote && (lm_trans_put(lm_lmx_message_thread, file, ", ") != 0)) {
            return 1;
        }
        if (field != 0) {
            next = lm_trans_expr_segment_end(lm_lmx_message_thread, field);
            if (lm_trans_node_is_positional_skip(lm_lmx_message_thread, field -> value)) {
                if (lm_trans_formal_param_default_fields(lm_lmx_message_thread, param_node, &default_first) == 0) {
                    return 1;
                }
                if (lm_trans_emit_expr_range(lm_lmx_message_thread, file, default_first, 0, namespace_) != 0) {
                    return 1;
                }
            }
            else {
                if (lm_trans_emit_expr_range(lm_lmx_message_thread, file, field, next, namespace_) != 0) {
                    return 1;
                }
            }
            field = next;
        }
        else {
            if (lm_trans_formal_param_default_fields(lm_lmx_message_thread, param_node, &default_first) == 0) {
                return 1;
            }
            if (lm_trans_emit_expr_range(lm_lmx_message_thread, file, default_first, 0, namespace_) != 0) {
                return 1;
            }
        }
        wrote = 1;
        index = index + 1U;
    }
    index = 0U;
    while (index < descriptor_param_count) {
        if (((descriptor_params[index] == 0) || (descriptor_params[index] -> name == 0)) || (descriptor_params[index] -> name[0] == '\0')) {
            return 1;
        }
        if (wrote && (lm_trans_put(lm_lmx_message_thread, file, ", ") != 0)) {
            return 1;
        }
        if (lm_trans_emit_identifier(lm_lmx_message_thread, file, lm_trans_text_from_cstr(lm_lmx_message_thread, descriptor_params[index] -> name)) != 0) {
            return 1;
        }
        wrote = 1;
        index = index + 1U;
    }
    return 0;
}

