static int lm_trans_profile_rule_enabled(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *rule) {
    (void)lm_lmx_message_thread;
    LmP0Text * rule_text;
    const char *policy;
    int enabled;
    if (rule == 0) {
        return 0;
    }
    rule_text = lm_trans_text_ref_new_cstr(rule);
    if (rule_text == 0) {
        return 0;
    }
    policy = lm_trans_c99_ub_policy_value(lm_lmx_message_thread, namespace_, rule_text);
    enabled = 0;
    if (policy != 0) {
        if (strcmp(policy, "diagnostic") == 0 || strcmp(policy, "checked") == 0) {
            enabled = 1;
        }
    }
    lm_trans_text_ref_destroy(&rule_text);
    return enabled;
}

static int lm_trans_profile_validator_enabled(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *rule, const char *binding_name) {
    (void)lm_lmx_message_thread;
    LmP0Text * rule_text;
    const char *binding;
    int enabled;
    if (rule == 0 || binding_name == 0) {
        return 0;
    }
    if (lm_trans_profile_rule_enabled(lm_lmx_message_thread, namespace_, rule) == 0) {
        return 0;
    }
    rule_text = lm_trans_text_ref_new_cstr(rule);
    if (rule_text == 0) {
        return 0;
    }
    binding = lm_trans_profile_validator_binding(lm_lmx_message_thread, namespace_, rule_text);
    enabled = binding != 0 && strcmp(binding, binding_name) == 0;
    lm_trans_text_ref_destroy(&rule_text);
    return enabled;
}

static const char * lm_trans_printf_conversion_typed_value(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, char conversion, char modifier, const char *source_path, const char *value_column_name, const char *value_descriptor) {
    (void)lm_lmx_message_thread;
    char key_buffer[5];
    const char *key_data = key_buffer;
    LmP0Text * key;
    const char *value;
    size_t index;
    if (source_path == 0 || value_column_name == 0 || value_descriptor == 0) {
        return 0;
    }
    key = lm_trans_text_ref_new_cstr("");
    if (key == 0) {
        return 0;
    }
    index = 0U;
    key_buffer[index] = '%';
    index = index + 1U;
    if (modifier != '\0') {
        key_buffer[index] = modifier;
        index = index + 1U;
    }
    key_buffer[index] = conversion;
    index = index + 1U;
    key_buffer[index] = '\0';
    key->data = key_data;
    key->length = index;
    value = lm_trans_namespace_registry_source_path_n2_named_typed_value(lm_lmx_message_thread, namespace_, key, source_path, "class", "class", value_column_name, value_descriptor);
    lm_trans_text_ref_destroy(&key);
    return value;
}

static void lm_trans_printf_conversion_rule_resolve(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, char conversion, char modifier, const char **out_expected, const char **out_profile) {
    (void)lm_lmx_message_thread;
    const char *expected;
    const char *profile;
    if (out_expected == 0 || out_profile == 0) {
        return;
    }
    expected = lm_trans_printf_conversion_typed_value(lm_lmx_message_thread, namespace_, conversion, modifier, "printf.conversion.rule.expected", "expected", "class");
    if (expected == 0) {
        expected = lm_trans_printf_conversion_typed_value(lm_lmx_message_thread, namespace_, conversion, modifier, "printf.argument.class", "value", "class");
    }
    profile = lm_trans_printf_conversion_typed_value(lm_lmx_message_thread, namespace_, conversion, modifier, "printf.conversion.rule.profile", "profile", "profileRule");
    if (profile == 0 && expected != 0) {
        profile = "c99.format-mismatch";
    }
    out_expected[0] = expected;
    out_profile[0] = profile;
}

static int lm_trans_validate_printf_expected_arg(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, const LmTransNamespace *namespace_, size_t arg_index, const char *expected_class) {
    (void)lm_lmx_message_thread;
    const LmP0Field * first;
    const LmP0Field * stop;
    LmP0Text * actual_class;
    int status;
    if (lm_trans_c_call_arg_segment_at(lm_lmx_message_thread, frame -> body, arg_index, &first, &stop) == 0) {
        fprintf(stderr, "trans L2 format error: %.*s format expects argument %zu\n", (((int)frame -> head -> length)), frame -> head -> data, arg_index + 1U);
        return 1;
    }
    if (expected_class == 0) {
        return 0;
    }
    actual_class = lm_trans_text_ref_new_cstr("");
    if (actual_class == 0) {
        return 1;
    }
    status = 0;
    if (lm_trans_printf_arg_class_from_segment(lm_lmx_message_thread, first, stop, namespace_, actual_class)) {
        if (lm_trans_text_equals(lm_lmx_message_thread, actual_class, expected_class) == 0) {
            fprintf(stderr, "trans L2 format error: %.*s argument %zu expects %s, got %.*s\n", (((int)frame -> head -> length)), frame -> head -> data, arg_index + 1U, expected_class, (((int)actual_class -> length)), actual_class -> data);
            status = 1;
        }
    }
    lm_trans_text_ref_destroy(&actual_class);
    return status;
}

static int lm_trans_validate_c_printf_call(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * format_first;
    const LmP0Field * format_stop;
    const LmP0Node * format_node;
    LmP0Text * format_payload;
    const char *expected;
    const char *profile_rule;
    size_t format_index;
    size_t arg_index;
    size_t i;
    char modifier;
    char conversion;
    int status;
    if (frame == 0) {
        return 0;
    }
    if (lm_trans_c_printf_format_arg_index(lm_lmx_message_thread, frame -> head, &format_index) == 0) {
        return 0;
    }
    if (lm_trans_c_call_arg_segment_at(lm_lmx_message_thread, frame -> body, format_index, &format_first, &format_stop) == 0) {
        fprintf(stderr, "trans L2 format error: %.*s expects a literal format argument\n", (((int)frame -> head -> length)), frame -> head -> data);
        return 1;
    }
    format_node = lm_trans_c_arg_single_node(lm_lmx_message_thread, format_first, format_stop);
    if (format_node == 0 || format_node -> kind != LM_P0_NODE_ATOM) {
        return 0;
    }
    format_payload = lm_trans_text_ref_new_cstr("");
    if (format_payload == 0) {
        return 1;
    }
    if (lm_trans_format_atom_payload(lm_lmx_message_thread, format_node -> as -> atom, format_payload) == 0) {
        lm_trans_text_ref_destroy(&format_payload);
        return 0;
    }
    arg_index = format_index + 1U;
    i = 0U;
    status = 0;
    while (status == 0 && i < format_payload -> length) {
        if (format_payload -> data[i] != '%') {
            i = i + 1U;
            continue;
        }
        i = i + 1U;
        if (i >= format_payload -> length) {
            break;
        }
        if (format_payload -> data[i] == '%') {
            i = i + 1U;
            continue;
        }
        while (i < format_payload -> length && lm_trans_printf_format_is_flag(lm_lmx_message_thread, format_payload -> data[i])) {
            i = i + 1U;
        }
        if (i < format_payload -> length && format_payload -> data[i] == '*') {
            status = lm_trans_validate_printf_expected_arg(lm_lmx_message_thread, frame, namespace_, arg_index, "int");
            arg_index = arg_index + 1U;
            i = i + 1U;
        }
        else {
            while (i < format_payload -> length && format_payload -> data[i] >= '0' && format_payload -> data[i] <= '9') {
                i = i + 1U;
            }
        }
        if (status != 0) {
            break;
        }
        if (i < format_payload -> length && format_payload -> data[i] == '.') {
            i = i + 1U;
            if (i < format_payload -> length && format_payload -> data[i] == '*') {
                status = lm_trans_validate_printf_expected_arg(lm_lmx_message_thread, frame, namespace_, arg_index, "int");
                arg_index = arg_index + 1U;
                i = i + 1U;
            }
            else {
                while (i < format_payload -> length && format_payload -> data[i] >= '0' && format_payload -> data[i] <= '9') {
                    i = i + 1U;
                }
            }
        }
        if (status != 0) {
            break;
        }
        modifier = '\0';
        if (i < format_payload -> length) {
            if (format_payload -> data[i] == 'z') {
                modifier = 'z';
                i = i + 1U;
            }
            else {
                if (format_payload -> data[i] == 'l') {
                    modifier = 'l';
                    i = i + 1U;
                    if (i < format_payload -> length && format_payload -> data[i] == 'l') {
                        modifier = 'q';
                        i = i + 1U;
                    }
                }
                else {
                    if (format_payload -> data[i] == 'h' || format_payload -> data[i] == 'j' || format_payload -> data[i] == 't' || format_payload -> data[i] == 'L') {
                        modifier = format_payload -> data[i];
                        i = i + 1U;
                        if (i < format_payload -> length && format_payload -> data[i - 1U] == 'h' && format_payload -> data[i] == 'h') {
                            modifier = 'H';
                            i = i + 1U;
                        }
                    }
                }
            }
        }
        if (i >= format_payload -> length) {
            break;
        }
        conversion = format_payload -> data[i];
        i = i + 1U;
        expected = 0;
        profile_rule = 0;
        lm_trans_printf_conversion_rule_resolve(lm_lmx_message_thread, namespace_, conversion, modifier, &expected, &profile_rule);
        if (conversion != 'n') {
            if (profile_rule == 0 || lm_trans_profile_rule_enabled(lm_lmx_message_thread, namespace_, profile_rule)) {
                status = lm_trans_validate_printf_expected_arg(lm_lmx_message_thread, frame, namespace_, arg_index, expected);
            }
            arg_index = arg_index + 1U;
        }
    }
    lm_trans_text_ref_destroy(&format_payload);
    return status;
}

static int lm_trans_validate_profile_c_printf_call(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    if (lm_trans_profile_validator_enabled(lm_lmx_message_thread, namespace_, "c99.format-mismatch", "lm_trans_validate_c_printf_call") == 0) {
        return 0;
    }
    return lm_trans_validate_c_printf_call(lm_lmx_message_thread, frame, namespace_);
}

