static int lm_trans_lower_expr_atom(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *node, const LmP0Node *previous_operand, int expect_field_name, int expect_c_field_name, int c_dot_path, LmTransExprAtomLowering *out) {
    (void)lm_lmx_message_thread;
    if (((out == 0) || (node == 0)) || (node -> kind != LM_P0_NODE_ATOM)) {
        return 1;
    }
    lm_trans_expr_atom_lowering_set_builtin(lm_lmx_message_thread, out, node -> as -> atom, "lm_trans_expr_emit_value");
    if (expect_field_name) {
        lm_trans_expr_atom_lowering_set_builtin(lm_lmx_message_thread, out, node -> as -> atom, "lm_trans_expr_emit_field_name");
    }
    else {
        if (expect_c_field_name) {
            lm_trans_expr_atom_lowering_set_builtin(lm_lmx_message_thread, out, node -> as -> atom, "lm_trans_expr_emit_c_field_name");
        }
        else {
            if (lm_trans_is_c_reference_name(lm_lmx_message_thread, node -> as -> atom)) {
                lm_trans_expr_atom_lowering_set_builtin(lm_lmx_message_thread, out, node -> as -> atom, "lm_trans_expr_emit_c_surface");
            }
            else {
                if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> atom, "\\")) {
                    if ((previous_operand != 0) && (lm_trans_nodes_touch(lm_lmx_message_thread, previous_operand, node) || lm_trans_node_is_exact_quoted_identifier(lm_lmx_message_thread, previous_operand))) {
                        return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.infix");
                    }
                    else {
                        return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.prefix");
                    }
                }
                else {
                    if (lm_trans_registry_has_expr_emitter_binding(lm_lmx_message_thread, node -> as -> atom, "expr.atom.emitter")) {
                        return lm_trans_expr_atom_lowering_set_from_tables(lm_lmx_message_thread, out, node -> as -> atom, "expr.atom.ansi_c", "expr.atom.emitter");
                    }
                    else {
                        if (lm_trans_atom_is_index_operator(lm_lmx_message_thread, node -> as -> atom)) {
                            return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.index");
                        }
                        else {
                            if (lm_trans_atom_is_infix_expr_operator(lm_lmx_message_thread, node -> as -> atom, node, previous_operand)) {
                                return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.infix");
                            }
                            else {
                                if (lm_trans_text_is_operator_atom(lm_lmx_message_thread, node -> as -> atom)) {
                                    if (lm_trans_registry_has_expr_emitter_class(lm_lmx_message_thread, node -> as -> atom, "operator.prefix")) {
                                        return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.prefix");
                                    }
                                    if (lm_trans_registry_has_expr_emitter_class(lm_lmx_message_thread, node -> as -> atom, "operator.postfix")) {
                                        return lm_trans_expr_atom_lowering_set_from_class(lm_lmx_message_thread, out, node -> as -> atom, "operator.postfix");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    LM_UNUSED(c_dot_path);
    return 0;
}

