static int lm_trans_emit_c_dimension_text(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Text *dimension, const LmTransNamespace *namespace_, const char *error_name) {
    (void)lm_lmx_message_thread;
    LmP0Document * dimension_document;
    const LmP0Diagnostic * diagnostic;
    const LmP0Node * dimension_root;
    const char *effective_error_name;
    int parse_status;
    if ((dimension == 0) || (dimension -> length == 0U)) {
        return 0;
    }
    dimension_document = 0;
    effective_error_name = "array dimension";
    if (error_name != 0) {
        effective_error_name = error_name;
    }
    parse_status = lm_p0_parse_bytes(lm_lmx_message_thread, dimension -> data, dimension -> length, &dimension_document);
    if (parse_status != 0) {
        if (dimension_document != 0) {
            diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, dimension_document);
        }
        else {
            diagnostic = 0;
        }
        if (diagnostic != 0) {
            fprintf(stderr, "trans L2 error: %s parse error %d at %zu:%zu: %s\n", effective_error_name, diagnostic -> code, diagnostic -> line, diagnostic -> column, diagnostic -> message);
        }
        else {
            fprintf(stderr, "trans L2 error: %s parse failed\n", effective_error_name);
        }
        if (dimension_document != 0) {
            lm_p0_document_destroy(lm_lmx_message_thread, dimension_document);
        }
        return 1;
    }
    dimension_root = lm_p0_document_root(lm_lmx_message_thread, dimension_document);
    if (((dimension_root == 0) || (dimension_root -> kind != LM_P0_NODE_STRUCTURE)) || (dimension_root -> as -> structure -> first_field == 0)) {
        fprintf(stderr, "trans L2 error: %s must not be empty\n", effective_error_name);
        lm_p0_document_destroy(lm_lmx_message_thread, dimension_document);
        return 1;
    }
    if (lm_trans_emit_expr_fields(lm_lmx_message_thread, file, dimension_root -> as -> structure -> first_field, namespace_) != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, dimension_document);
        return 1;
    }
    lm_p0_document_destroy(lm_lmx_message_thread, dimension_document);
    return 0;
}

static int lm_trans_emit_c_declarator(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransCDeclarator *declarator, const LmTransNamespace *namespace_, const char *error_name) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t head_index;
    LmP0Text * head_dimension;
    const LmP0Field * expression_dimension;
    const char *effective_dimension_error_name;
    if ((file == 0) || (declarator == 0)) {
        return 1;
    }
    if (declarator -> type_is_head) {
        if (declarator -> type_head == 0) {
            return 1;
        }
        if (lm_trans_emit_type_head_only(lm_lmx_message_thread, file, declarator -> type_head, namespace_) != 0) {
            return 1;
        }
    }
    else {
        if ((declarator -> type_node == 0) || (lm_trans_emit_type_node(lm_lmx_message_thread, file, declarator -> type_node, namespace_) != 0)) {
            return 1;
        }
    }
    if (lm_trans_put(lm_lmx_message_thread, file, " ") != 0) {
        return 1;
    }
    i = 0U;
    while (i < declarator -> pointer_depth) {
        if (lm_trans_put(lm_lmx_message_thread, file, "*") != 0) {
            return 1;
        }
        i = i + 1U;
    }
    if ((declarator -> name == 0) || (lm_trans_emit_identifier(lm_lmx_message_thread, file, declarator -> name) != 0)) {
        return 1;
    }
    head_index = 0U;
    head_dimension = lm_trans_text_ref_new_cstr("");
    if (head_dimension == 0) {
        return 1;
    }
    effective_dimension_error_name = "array dimension";
    if (error_name != 0) {
        effective_dimension_error_name = error_name;
    }
    if (declarator -> array_head == 0) {
        return 1;
    }
    expression_dimension = declarator -> expression_dimensions;
    while (lm_trans_array_head_next_dimension(lm_lmx_message_thread, declarator -> array_head, &head_index, head_dimension)) {
        if (lm_trans_put(lm_lmx_message_thread, file, "[") != 0) {
            lm_trans_text_ref_destroy(&head_dimension);
            return 1;
        }
        if (head_dimension -> length != 0U) {
            if (lm_trans_emit_c_dimension_text(lm_lmx_message_thread, file, head_dimension, namespace_, error_name) != 0) {
                lm_trans_text_ref_destroy(&head_dimension);
                return 1;
            }
        }
        else {
            if (expression_dimension == 0 || expression_dimension -> value == 0 || (declarator -> atom_dimensions_only && lm_trans_array_body_dimension_can_consume(lm_lmx_message_thread, expression_dimension) == 0)) {
                if (declarator -> allow_empty_dimensions) {
                    if (lm_trans_put(lm_lmx_message_thread, file, "]") != 0) {
                        lm_trans_text_ref_destroy(&head_dimension);
                        return 1;
                    }
                    continue;
                }
                fprintf(stderr, "trans L2 error: %s expects a size expression\n", effective_dimension_error_name);
                lm_trans_text_ref_destroy(&head_dimension);
                return 1;
            }
            if (lm_trans_emit_expr_node(lm_lmx_message_thread, file, expression_dimension -> value, namespace_) != 0) {
                lm_trans_text_ref_destroy(&head_dimension);
                return 1;
            }
            expression_dimension = expression_dimension -> next;
        }
        if (lm_trans_put(lm_lmx_message_thread, file, "]") != 0) {
            lm_trans_text_ref_destroy(&head_dimension);
            return 1;
        }
    }
    lm_trans_text_ref_destroy(&head_dimension);
    i = 0U;
    while (i < declarator -> literal_dimension_count) {
        if (((lm_trans_put(lm_lmx_message_thread, file, "[") != 0) || (lm_trans_emit_size_literal(lm_lmx_message_thread, file, declarator -> literal_dimensions[i]) != 0)) || (lm_trans_put(lm_lmx_message_thread, file, "]") != 0)) {
            return 1;
        }
        i = i + 1U;
    }
    return 0;
}

static const LmP0Field * lm_trans_c_declarator_expression_dimension_tail(struct LmMessageThread *lm_lmx_message_thread, const LmTransCDeclarator *declarator) {
    (void)lm_lmx_message_thread;
    const LmP0Field * dimension;
    size_t head_index;
    LmP0Text * head_dimension;
    if (declarator == 0) {
        return 0;
    }
    dimension = declarator -> expression_dimensions;
    if (declarator -> array_head == 0) {
        return dimension;
    }
    head_index = 0U;
    head_dimension = lm_trans_text_ref_new_cstr("");
    if (head_dimension == 0) {
        return dimension;
    }
    while (lm_trans_array_head_next_dimension(lm_lmx_message_thread, declarator -> array_head, &head_index, head_dimension)) {
        if (head_dimension -> length == 0U && dimension != 0 && dimension -> value != 0 && (declarator -> atom_dimensions_only == 0 || lm_trans_array_body_dimension_can_consume(lm_lmx_message_thread, dimension))) {
            dimension = dimension -> next;
        }
    }
    {
        const LmP0Field * lm_return_0 = dimension;
        lm_trans_text_ref_destroy(&head_dimension);
        return lm_return_0;
    }
    lm_trans_text_ref_destroy(&head_dimension);
}

static int lm_trans_emit_array_param(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransFormalParam *param, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    char *param_c_name;
    LmP0Text * param_c_name_text;
    LmP0Text * slice_type;
    int status;
    if (param == 0 || param -> declarator == 0 || param -> has_name == 0 || param -> type == 0 || param -> type -> class_name == 0 || param -> type -> array_rank == 0U || param -> type -> address_depth == 0U) {
        return 1;
    }
    slice_type = lm_trans_text_ref_new_cstr("LmSlice");
    param_c_name = lm_trans_array_param_c_name_new(lm_lmx_message_thread, param);
    param_c_name_text = lm_trans_text_from_cstr(lm_lmx_message_thread, param_c_name);
    if (slice_type == 0 || param_c_name == 0 || param_c_name_text == 0) {
        lm_own_delete(param_c_name, 0);
        lm_trans_text_ref_destroy(&param_c_name_text);
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, "LmSlice *") != 0 || lm_trans_write_text(lm_lmx_message_thread, file, param_c_name_text) != 0) {
        {
            int lm_return_0 = 1;
            lm_trans_text_ref_destroy(&slice_type);
            lm_trans_text_ref_destroy(&param_c_name_text);
            lm_own_delete(param_c_name, 0);
            return lm_return_0;
        }
    }
    status = lm_trans_namespace_declare_c_name(lm_lmx_message_thread, namespace_, param -> name, "variable", param_c_name_text);
    if (status != 0) {
        {
            int lm_return_1 = 1;
            lm_trans_text_ref_destroy(&slice_type);
            lm_trans_text_ref_destroy(&param_c_name_text);
            lm_own_delete(param_c_name, 0);
            return lm_return_1;
        }
    }
    status = lm_trans_namespace_declare_relation_text(lm_lmx_message_thread, namespace_, param -> name, "variable.type", slice_type);
    if (status == 0) {
        status = lm_trans_namespace_mark_array_reference(lm_lmx_message_thread, namespace_, param -> name, param -> type -> array_rank, param -> type -> address_depth - 1U, param -> type -> is_const);
    }
    if (status == 0) {
        status = lm_trans_namespace_declare_relation_text(lm_lmx_message_thread, namespace_, param -> name, "variable.array-element-type", param -> type -> class_name);
    }
    if (status == 0) {
        status = lm_trans_namespace_declare_relation_text(lm_lmx_message_thread, namespace_, param -> name, "variable.slice-name", param_c_name_text);
    }
    {
        int lm_return_2 = status;
        lm_trans_text_ref_destroy(&slice_type);
        lm_trans_text_ref_destroy(&param_c_name_text);
        lm_own_delete(param_c_name, 0);
        return lm_return_2;
    }
    lm_trans_text_ref_destroy(&slice_type);
    lm_trans_text_ref_destroy(&param_c_name_text);
    lm_own_delete(param_c_name, 0);
}

static int lm_trans_emit_formal_param(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransFormalParam *param, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int status;
    if (param == 0) {
        return 1;
    }
    if (param -> source_node == 0 || param -> source_node -> kind != LM_P0_NODE_FRAME) {
        if (lm_trans_node_is_positional_skip(lm_lmx_message_thread, param -> source_node)) {
            fprintf(stderr, "trans L2 error: skipped function parameter has no default declaration in this profile\n");
            return 1;
        }
        fprintf(stderr, "trans L2 error: parameter must be a typed frame\n");
        return 1;
    }
    if (param -> is_array) {
        return lm_trans_emit_array_param(lm_lmx_message_thread, file, param, namespace_);
    }
    if (param -> has_name == 0) {
        fprintf(stderr, "trans L2 error: typed parameter expects a name\n");
        return 1;
    }
    if (lm_trans_symbol_is(lm_lmx_message_thread, lm_trans_namespace_find(lm_lmx_message_thread, namespace_, param -> type -> class_name), "callableDescriptor") && lm_trans_callable_descriptor_is_raw_function_reference(lm_lmx_message_thread, namespace_, param -> type -> class_name)) {
        if (lm_trans_emit_raw_callable_declarator(lm_lmx_message_thread, file, namespace_, param -> type -> class_name, param -> name, "callable descriptor parameter") != 0) {
            return 1;
        }
        return lm_trans_namespace_declare_storage_binding(lm_lmx_message_thread, namespace_, param -> name, param -> type -> class_name);
    }
    status = lm_trans_emit_callable_type_named(lm_lmx_message_thread, file, param -> type, param -> name, namespace_);
    if (status == 0) {
        status = lm_trans_namespace_declare_storage_binding(lm_lmx_message_thread, namespace_, param -> name, param -> type -> class_name);
    }
    if (status == 0 && param -> type -> address_depth != 0U) {
        status = lm_trans_namespace_mark_raw_pointer(lm_lmx_message_thread, namespace_, param -> name, param -> type -> address_depth, param -> type -> is_const);
    }
    return status;
}

