static int lm_trans_emit_capture_field(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransCapture *capture, unsigned indent, size_t extra_pointer_depth, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    if (capture == 0) {
        return 1;
    }
    if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent) != 0) {
        return 1;
    }
    if (capture -> type_is_head) {
        if (lm_trans_emit_type_head_only(lm_lmx_message_thread, file, capture -> type_head, namespace_) != 0) {
            return 1;
        }
    }
    if (capture -> type_is_head == 0) {
        if (lm_trans_emit_type_node(lm_lmx_message_thread, file, capture -> type_node, namespace_) != 0) {
            return 1;
        }
    }
    if (lm_trans_put(lm_lmx_message_thread, file, " ") != 0) {
        return 1;
    }
    i = 0U;
    while (i < capture -> pointer_depth + extra_pointer_depth) {
        if (lm_trans_put(lm_lmx_message_thread, file, "*") != 0) {
            return 1;
        }
        i = i + 1U;
    }
    if (lm_trans_emit_identifier(lm_lmx_message_thread, file, capture -> name) != 0) {
        return 1;
    }
    return lm_trans_put(lm_lmx_message_thread, file, ";\n");
}

static int lm_trans_emit_env_type_raw(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransFunctionHeader *function, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    const LmTransCapture * capture;
    if (function == 0 || function -> has_env == 0 || function -> captures == 0) {
        return 0;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, "typedef struct ") != 0) {
        return 1;
    }
    if (lm_trans_write_text(lm_lmx_message_thread, file, function -> env_type_name) != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, " ") != 0) {
        return 1;
    }
    if (lm_trans_write_text(lm_lmx_message_thread, file, function -> env_type_name) != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, ";\n\nstruct ") != 0) {
        return 1;
    }
    if (lm_trans_write_text(lm_lmx_message_thread, file, function -> env_type_name) != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, " {\n") != 0) {
        return 1;
    }
    i = 0U;
    while (i < function -> captures -> count) {
        capture = (((const LmTransCapture *)lm_own_ptr_stack_at(function -> captures, i)));
        if (lm_trans_emit_capture_field(lm_lmx_message_thread, file, capture, 1U, 0U, namespace_) != 0) {
            return 1;
        }
        i = i + 1U;
    }
    return lm_trans_put(lm_lmx_message_thread, file, "};\n\n");
}

static int lm_trans_emit_env_type(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmTransFunctionHeader *function, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    FILE * declaration_file;
    int emitted;
    int status;
    if (function == 0 || function -> has_env == 0 || function -> captures == 0) {
        return 0;
    }
    declaration_file = lm_trans_tmpfile(lm_lmx_message_thread);
    if (declaration_file == 0) {
        return 1;
    }
    status = lm_trans_emit_env_type_raw(lm_lmx_message_thread, declaration_file, function, namespace_);
    if (status == 0) {
        status = lm_trans_typedef_projection_emit_prepared_text(lm_lmx_message_thread, file, function -> env_type_name, declaration_file, &emitted);
    }
    fclose(declaration_file);
    return status;
}

static const LmP0Field * lm_trans_control_body_start(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    const LmP0Field * end_field;
    if (frame == 0 || frame -> body -> first_field == 0) {
        return 0;
    }
    end_field = lm_trans_expr_segment_end(lm_lmx_message_thread, frame -> body -> first_field);
    if (end_field != 0 && end_field -> value != 0 && end_field -> value -> kind == LM_P0_NODE_STRUCTURE) {
        return end_field;
    }
    return 0;
}

