static int lm_trans_l2_table_prepare_source_rows(struct LmMessageThread *lm_lmx_message_thread, LmTableDescriptor *target, const LmP0Frame *rows_frame, size_t column_count, size_t row_count, int require_facade, size_t *out_first_row_index) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * *cells;
    size_t initial_row_count;
    size_t row_index;
    size_t column_index;
    int status;
    if (target == 0 || target -> materialized_rows == 0 || rows_frame == 0 || column_count == 0U) {
        return 1;
    }
    initial_row_count = lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, target);
    if (out_first_row_index != 0) {
        out_first_row_index[0] = initial_row_count;
    }
    cells = (((const LmP0Node * *)lm_own_new_zero(column_count * sizeof(cells[0]))));
    if (cells == 0) {
        return 1;
    }
    status = 0;
    field = lm_trans_l2_structure_first_present_field(lm_lmx_message_thread, rows_frame -> body);
    row_index = 0U;
    while (status == 0 && row_index < row_count) {
        column_index = 0U;
        while (status == 0 && column_index < column_count) {
            if (field == 0 || field -> value == 0) {
                status = 1;
            }
            else {
                cells[column_index] = field -> value;
                field = lm_trans_l2_structure_next_present_field(lm_lmx_message_thread, field);
            }
            column_index = column_index + 1U;
        }
        if (status == 0 && lm_trans_registry_prepare_source_descriptor_row(lm_lmx_message_thread, target, cells, column_count, require_facade) != 0) {
            status = 1;
        }
        row_index = row_index + 1U;
    }
    if (status == 0 && field != 0) {
        status = 1;
    }
    lm_own_delete(cells, 0);
    if (status != 0) {
        lm_own_ptr_stack_truncate(target -> materialized_rows, initial_row_count);
        return 1;
    }
    return 0;
}

static int lm_trans_l2_table_project_source_rows(struct LmMessageThread *lm_lmx_message_thread, LmTableDescriptor *target, size_t first_row_index) {
    (void)lm_lmx_message_thread;
    LmTableRow * prepared_row;
    size_t row_index;
    if (target == 0 || first_row_index > lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, target)) {
        return 1;
    }
    row_index = first_row_index;
    while (row_index < lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, target)) {
        prepared_row = lm_own_ptr_stack_at(target -> materialized_rows, row_index);
        if (lm_trans_registry_project_source_descriptor_row(lm_lmx_message_thread, target, prepared_row) != 0) {
            return 1;
        }
        row_index = row_index + 1U;
    }
    return 0;
}

static int lm_trans_l2_table_materialize_source_rows(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Text *table_name, const LmP0Frame *rows_frame, LmTransL4CallableType **column_types, LmP0Text **column_names, size_t column_count, size_t row_count, int require_facade) {
    (void)lm_lmx_message_thread;
    LmRegistryView * view;
    LmTableDescriptor * candidate;
    LmTableDescriptor * target;
    LmTableDescriptor * existing;
    size_t initial_row_count;
    int candidate_is_target;
    int status;
    view = 0;
    if (lm_trans_registry != 0 && lm_trans_namespace_registry_view(lm_lmx_message_thread, namespace_) == lm_trans_registry->view) {
        view = lm_trans_registry->view;
    }
    if (view == 0) {
        return require_facade != 0;
    }
    candidate = lm_trans_l2_table_source_descriptor_new(lm_lmx_message_thread, table_name, column_types, column_names, column_count);
    if (candidate == 0) {
        return 1;
    }
    target = candidate;
    candidate_is_target = 1;
    existing = lm_registry_view_find_local_source_table_slice(lm_lmx_message_thread, view, candidate -> name, strlen(candidate -> name));
    if (existing != 0 && lm_table_descriptor_schema_same(lm_lmx_message_thread, existing, candidate) != 0) {
        target = existing;
        candidate_is_target = 0;
        lm_table_descriptor_delete_any(candidate);
        candidate = 0;
    }
    initial_row_count = lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, target);
    status = lm_trans_l2_table_prepare_source_rows(lm_lmx_message_thread, target, rows_frame, column_count, row_count, require_facade, 0);
    if (status == 0 && lm_trans_registry_preflight_source_descriptor_class_kinds(lm_lmx_message_thread, target, initial_row_count) != 0) {
        status = 1;
    }
    if (status == 0 && lm_trans_l2_table_project_source_rows(lm_lmx_message_thread, target, initial_row_count) != 0) {
        status = 1;
    }
    if (status != 0) {
        lm_own_ptr_stack_truncate(target -> materialized_rows, initial_row_count);
        if (candidate_is_target != 0) {
            lm_table_descriptor_delete_any(target);
        }
        return 1;
    }
    if (candidate_is_target != 0) {
        if (lm_registry_view_take_local_source_table(lm_lmx_message_thread, view, target) != 0) {
            lm_table_descriptor_delete_any(target);
            return 1;
        }
    }
    else {
        if (lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, target) != initial_row_count) {
            lm_registry_view_note_mutation(lm_lmx_message_thread, view);
        }
    }
    return 0;
}

