static int lm_trans_l2_join_body_rows(struct LmMessageThread *lm_lmx_message_thread, const LmP0Structure *body, const LmP0Frame **out_rows) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Frame * child;
    int have_columns;
    int have_rows;
    int source_marker;
    if (body == 0 || out_rows == 0) {
        return 1;
    }
    out_rows[0] = 0;
    if (lm_trans_l2_body_source_marker(lm_lmx_message_thread, body, "join", &source_marker) != 0) {
        return 1;
    }
    have_columns = 0;
    have_rows = 0;
    field = lm_trans_l2_structure_first_present_field(lm_lmx_message_thread, body);
    if (source_marker != 0) {
        field = lm_trans_l2_structure_next_present_field(lm_lmx_message_thread, field);
    }
    while (field != 0) {
        if (field -> value == 0 || field -> value -> kind != LM_P0_NODE_FRAME) {
            fprintf(stderr, "trans L2 join error: join body expects an optional first source marker followed by columns/rows frames\n");
            return 1;
        }
        child = field -> value -> as -> frame;
        if (lm_trans_text_equals(lm_lmx_message_thread, child -> head, "columns")) {
            if (have_columns != 0) {
                fprintf(stderr, "trans L2 join error: join expects exactly one columns frame\n");
                return 1;
            }
            have_columns = 1;
        }
        else {
            if (lm_trans_text_equals(lm_lmx_message_thread, child -> head, "rows")) {
                if (have_rows != 0) {
                    fprintf(stderr, "trans L2 join error: join expects at most one rows frame\n");
                    return 1;
                }
                have_rows = 1;
                out_rows[0] = child;
            }
            else {
                fprintf(stderr, "trans L2 join error: join body expects an optional first source marker followed by columns/rows frames\n");
                return 1;
            }
        }
        field = lm_trans_l2_structure_next_present_field(lm_lmx_message_thread, field);
    }
    if (have_columns == 0) {
        fprintf(stderr, "trans L2 join error: join requires target columns\n");
        return 1;
    }
    return 0;
}

