static int lm_trans_l2_join_pending_descriptor_class_kind_conflicts(struct LmMessageThread *lm_lmx_message_thread, const LmTableDescriptor *descriptor, size_t first_row_index, const char *name, const char *kind) {
    (void)lm_lmx_message_thread;
    const LmTableRow * row;
    const LmTableCell * key_cell;
    const LmTableCell * payload_cell;
    size_t row_count;
    size_t row_index;
    size_t column_count;
    size_t column_index;
    int relation_status;
    if (descriptor == 0 || descriptor -> materialized_rows == 0 || name == 0 || kind == 0) {
        return 1;
    }
    row_count = lm_table_descriptor_materialized_row_count(lm_lmx_message_thread, descriptor);
    column_count = lm_table_descriptor_column_count(lm_lmx_message_thread, descriptor);
    if (first_row_index > row_count || column_count == 0U) {
        return 1;
    }
    row_index = first_row_index;
    while (row_index < row_count) {
        row = lm_table_descriptor_materialized_row_at(lm_lmx_message_thread, descriptor, row_index);
        if (row == 0 || lm_table_row_cell_count(lm_lmx_message_thread, row) != column_count) {
            return 1;
        }
        if (row -> source_native == 0) {
            key_cell = lm_table_row_cell_at(lm_lmx_message_thread, row, 0U);
            if (key_cell == 0 || key_cell -> value == 0 || key_cell -> node != 0) {
                return 1;
            }
            column_index = 1U;
            while (column_index < column_count) {
                payload_cell = lm_table_row_cell_at(lm_lmx_message_thread, row, column_index);
                relation_status = lm_trans_registry_source_descriptor_column_declares_class_kind(lm_lmx_message_thread, descriptor, column_index);
                if (payload_cell == 0 || relation_status < 0 || (payload_cell -> value != 0 && payload_cell -> node != 0)) {
                    return 1;
                }
                if (relation_status != 0 && payload_cell -> value != 0 && strcmp(key_cell -> value, name) == 0 && strcmp(payload_cell -> value, kind) != 0) {
                    fprintf(stderr, "trans registry class error: class %s has conflicting kinds %s and %s\n", name, payload_cell -> value, kind);
                    return 1;
                }
                column_index = column_index + 1U;
            }
        }
        row_index = row_index + 1U;
    }
    return 0;
}

