static int lm_trans_emit_struct_field_with_qualifier(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Node *node, unsigned indent, const char *qualifier, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Node * current;
    const LmP0Frame * frame;
    const LmP0Field * type_field;
    const LmP0Field * name_field;
    const LmP0Node * name_node;
    const char *current_qualifier;
    current = node;
    current_qualifier = qualifier;
    while (1) {
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, current)) {
            return 0;
        }
        if (current == 0 || current -> kind != LM_P0_NODE_FRAME) {
            fprintf(stderr, "trans L2 error: structure field must be a named field\n");
            return 1;
        }
        frame = current -> as -> frame;
        if (lm_trans_text_equals(lm_lmx_message_thread, frame -> head, "const") == 0) {
            break;
        }
        name_field = frame -> body -> first_field;
        if (name_field == 0 || name_field -> next != 0 || name_field -> value == 0 || name_field -> value -> kind != LM_P0_NODE_FRAME) {
            fprintf(stderr, "trans L2 error: const structure field expects exactly one field declaration\n");
            return 1;
        }
        current_qualifier = "const ";
        current = name_field -> value;
    }
    if (lm_trans_text_all_char(lm_lmx_message_thread, frame -> head, '@')) {
        type_field = lm_trans_nth_field(lm_lmx_message_thread, frame -> body, 0U);
        name_field = lm_trans_nth_field(lm_lmx_message_thread, frame -> body, 1U);
        if (type_field == 0 || name_field == 0 || name_field -> next != 0 || name_field -> value == 0 || name_field -> value -> kind != LM_P0_NODE_ATOM) {
            fprintf(stderr, "trans L2 error: pointer structure field expects type and name\n");
            return 1;
        }
        name_node = name_field -> value;
        if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent) != 0) {
            return 1;
        }
        if (current_qualifier != 0 && lm_trans_put(lm_lmx_message_thread, file, current_qualifier) != 0) {
            return 1;
        }
        if (lm_trans_emit_type_and_name(lm_lmx_message_thread, file, type_field -> value, name_node -> as -> atom, frame -> head -> length, namespace_) != 0) {
            return 1;
        }
        return lm_trans_put(lm_lmx_message_thread, file, ";\n");
    }
    name_field = lm_trans_nth_field(lm_lmx_message_thread, frame -> body, 0U);
    if (name_field == 0 || name_field -> next != 0 || name_field -> value == 0 || name_field -> value -> kind != LM_P0_NODE_ATOM) {
        fprintf(stderr, "trans L2 error: structure field expects Type: name\n");
        return 1;
    }
    if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent) != 0) {
        return 1;
    }
    if (current_qualifier != 0 && lm_trans_put(lm_lmx_message_thread, file, current_qualifier) != 0) {
        return 1;
    }
    if (lm_trans_emit_type_head_only(lm_lmx_message_thread, file, frame -> head, namespace_) != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, " ") != 0) {
        return 1;
    }
    if (lm_trans_emit_identifier(lm_lmx_message_thread, file, name_field -> value -> as -> atom) != 0) {
        return 1;
    }
    return lm_trans_put(lm_lmx_message_thread, file, ";\n");
}

