static int lm_trans_emit_function_return_structure_once(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Text *function_name, const LmP0Node *return_node, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    char *type_name;
    LmP0Text * type_name_text;
    const char *stored_name;
    FILE * declaration_file;
    int emitted;
    int status;
    type_name = lm_trans_function_return_struct_type_name_new(lm_lmx_message_thread, function_name);
    if (type_name == 0) {
        return 1;
    }
    declaration_file = lm_trans_tmpfile(lm_lmx_message_thread);
    if (declaration_file == 0) {
        lm_own_delete(type_name, 0);
        return 1;
    }
    status = lm_trans_emit_function_return_structure(lm_lmx_message_thread, declaration_file, function_name, return_node, namespace_);
    if (status == 0) {
        status = lm_trans_typedef_projection_emit_prepared_cstr(lm_lmx_message_thread, file, type_name, declaration_file, &emitted);
    }
    fclose(declaration_file);
    if (status != 0) {
        lm_own_delete(type_name, 0);
        return 1;
    }
    stored_name = lm_trans_string_stack_find(lm_lmx_message_thread, lm_trans_emitted_function_return_structs, type_name);
    if (stored_name != 0) {
        lm_own_delete(type_name, 0);
        return 0;
    }
    type_name_text = lm_trans_text_from_cstr(lm_lmx_message_thread, type_name);
    if (type_name_text == 0) {
        lm_own_delete(type_name, 0);
        return 1;
    }
    if (lm_trans_register_function_return_layout(lm_lmx_message_thread, type_name_text, return_node, namespace_) != 0) {
        lm_trans_text_ref_destroy(&type_name_text);
        lm_own_delete(type_name, 0);
        return 1;
    }
    lm_trans_text_ref_destroy(&type_name_text);
    if (lm_own_ptr_stack_push(lm_trans_emitted_function_return_structs, type_name) != 0) {
        lm_own_delete(type_name, 0);
        return 1;
    }
    return 0;
}

