static int lm_trans_statement_emit_assert(struct LmMessageThread *lm_lmx_message_thread, FILE *file, LmTransStatementStack *stack, const LmP0Frame *frame, unsigned indent, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    LM_UNUSED(stack);
    if (frame == 0 || frame -> body == 0 || frame -> body -> first_field == 0) {
        fprintf(stderr, "trans L2 error: assert receiver expects condition expression\n");
        return 1;
    }
    if (lm_trans_emit_message_thread_assert_helper(lm_lmx_message_thread, lm_trans_prelude_file(lm_lmx_message_thread, file)) != 0) {
        return 1;
    }
    if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent) != 0 || lm_trans_put(lm_lmx_message_thread, file, "if (!(") != 0) {
        return 1;
    }
    if (lm_trans_emit_control_condition(lm_lmx_message_thread, file, frame, namespace_) != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, file, ")) {\n") != 0) {
        return 1;
    }
    if (lm_trans_emit_cleanups_until(lm_lmx_message_thread, file, indent + 1U, namespace_, 0U) != 0) {
        return 1;
    }
    if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent + 1U) != 0 || lm_trans_put(lm_lmx_message_thread, file, "lm_message_thread_assert_violation(lm_lmx_message_thread, __FILE__, __LINE__, \"assert\");\n") != 0) {
        return 1;
    }
    if (lm_trans_emit_indent(lm_lmx_message_thread, file, indent) != 0 || lm_trans_put(lm_lmx_message_thread, file, "}\n") != 0) {
        return 1;
    }
    return 0;
}

