static int lm_trans_top_level_declare_generated_return_class(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmTransFunctionHeader *function) {
    (void)lm_lmx_message_thread;
    char *return_type_name_storage;
    LmP0Text * return_type_name;
    const LmTransSymbol * existing;
    int status;
    if (function == 0 || function -> is_struct_return == 0) {
        return 0;
    }
    return_type_name_storage = lm_trans_function_return_struct_type_name_new(lm_lmx_message_thread, function -> c_name);
    if (return_type_name_storage == 0) {
        return 1;
    }
    return_type_name = lm_trans_text_from_cstr(lm_lmx_message_thread, return_type_name_storage);
    if (return_type_name == 0) {
        lm_own_delete(return_type_name_storage, 0);
        return 1;
    }
    existing = lm_trans_namespace_find(lm_lmx_message_thread, namespace_, return_type_name);
    status = lm_trans_namespace_declare_generated(lm_lmx_message_thread, namespace_, return_type_name, "class");
    if (status == 0 && existing == 0) {
        status = lm_trans_registry_note_class_present(lm_lmx_message_thread, return_type_name) != 0 || lm_trans_registry_note_class_kind(lm_lmx_message_thread, return_type_name, "layout") != 0 || lm_trans_registry_note_class_reference_base(lm_lmx_message_thread, return_type_name) != 0 || lm_trans_registry_note_layout_backend(lm_lmx_message_thread, return_type_name, "c.struct") != 0;
    }
    lm_trans_text_ref_destroy(&return_type_name);
    lm_own_delete(return_type_name_storage, 0);
    return status;
}

static int lm_trans_top_level_declare_function_params(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmTransFunctionHeader *function) {
    (void)lm_lmx_message_thread;
    LmTransFormalParam * param;
    size_t index;
    int status;
    if (namespace_ == 0 || function == 0) {
        return 1;
    }
    if (function -> params == 0) {
        return 0;
    }
    status = 0;
    index = 0U;
    while (status == 0 && index < function -> params -> count) {
        param = function -> params -> params[index];
        if (lm_trans_namespace_declare_storage_binding(lm_lmx_message_thread, namespace_, param -> name, param -> type -> class_name) != 0) {
            status = 1;
        }
        index = index + 1U;
    }
    return status;
}

static int lm_trans_function_thread_context_profile(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const LmP0Text *name, int is_external, int *out_has_thread_context) {
    (void)lm_lmx_message_thread;
    int managed_context;
    int no_context;
    if (name == 0 || out_has_thread_context == 0) {
        return 1;
    }
    managed_context = lm_trans_namespace_registry_source_path_n2_named_typed_value(lm_lmx_message_thread, namespace_, name, "fn.thread-context.managed", "class", "class", "value", "int") != 0;
    no_context = lm_trans_namespace_registry_source_path_n2_named_typed_value(lm_lmx_message_thread, namespace_, name, "fn.thread-context.none", "class", "class", "value", "int") != 0;
    if (managed_context && no_context) {
        fprintf(stderr, "trans L2 error: function \"%.*s\" has conflicting thread-context profiles\n", (((int)name -> length)), name -> data);
        return 1;
    }
    if (is_external && managed_context && lm_trans_text_equals(lm_lmx_message_thread, name, "main")) {
        fprintf(stderr, "trans L2 error: external main cannot declare a managed thread-context ABI\n");
        return 1;
    }
    if (no_context) {
        out_has_thread_context[0] = 0;
    }
    else {
        if (lm_trans_registry_is_function_pointer_type_name(lm_lmx_message_thread, namespace_, name)) {
            out_has_thread_context[0] = managed_context;
        }
        else {
            if (is_external) {
                out_has_thread_context[0] = managed_context;
            }
            else {
                out_has_thread_context[0] = 1;
            }
        }
    }
    return 0;
}

static int lm_trans_function_apply_thread_context_profile(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, LmTransFunctionHeader *function) {
    (void)lm_lmx_message_thread;
    if (function == 0) {
        return 1;
    }
    return lm_trans_function_thread_context_profile(lm_lmx_message_thread, namespace_, function -> name, function -> is_external, &function -> has_thread_context);
}

static int lm_trans_top_level_note_module_init_main(struct LmMessageThread *lm_lmx_message_thread, const LmTransFunctionHeader *function) {
    (void)lm_lmx_message_thread;
    if (function == 0 || function -> is_external == 0 || lm_trans_text_equals(lm_lmx_message_thread, function -> c_name, "main") == 0) {
        return 0;
    }
    if (lm_trans_module_init_root_source_path == 0) {
        return 0;
    }
    if (lm_trans_current_source_path == 0 || strcmp(lm_trans_current_source_path, lm_trans_module_init_root_source_path) != 0) {
        fprintf(stderr, "trans hosted module-init limitation: an imported module cannot declare external main\n");
        return 1;
    }
    if (lm_trans_l2_conditional_import_depth > 0 || lm_trans_l2_conditional_emission_depth > 0 || lm_trans_module_init_unsupported_wrapper_depth > 0) {
        lm_trans_module_init_wrapped_main_seen = 1;
    }
    if (lm_trans_module_init_root_main_count != 0U) {
        fprintf(stderr, "trans hosted module-init limitation: a document cannot declare multiple external main functions\n");
        return 1;
    }
    lm_trans_module_init_root_main_count = 1U;
    return 0;
}

static int lm_trans_top_level_declare_function(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmTransTopLevelItem *item) {
    (void)lm_lmx_message_thread;
    if (item == 0 || item -> function == 0) {
        return 1;
    }
    if (lm_trans_function_apply_thread_context_profile(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    if (lm_trans_registry_note_class_kind(lm_lmx_message_thread, item -> function -> name, item -> function -> symbol_class) != 0) {
        return 1;
    }
    if (lm_trans_namespace_declare(lm_lmx_message_thread, namespace_, item -> function -> name, item -> function -> symbol_class) != 0) {
        return 1;
    }
    if (lm_trans_namespace_set_callable_shape(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    if (item -> function -> is_thread_handler) {
        if (lm_trans_current_source_path != 0 && lm_trans_registry_path_is_predefined(lm_lmx_message_thread, lm_trans_current_source_path)) {
            fprintf(stderr, "trans L2 error: executable thread declarations are not allowed in predef modules; use import\n");
            return 1;
        }
        if (lm_trans_l2_conditional_import_depth > 0) {
            fprintf(stderr, "trans L2 error: thread declarations are not supported inside os/ifdef/guard\n");
            return 1;
        }
        if (lm_trans_namespace_add_thread_declaration(lm_lmx_message_thread, namespace_, item -> function) != 0) {
            return 1;
        }
    }
    if (lm_trans_top_level_declare_generated_return_class(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    return lm_trans_top_level_note_module_init_main(lm_lmx_message_thread, item -> function);
}

static int lm_trans_top_level_is_predefined_function_descriptor(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const LmTransTopLevelItem *item) {
    (void)lm_lmx_message_thread;
    const LmTransFunctionHeader * function;
    if (item == 0) {
        return 0;
    }
    function = item -> function;
    if (function == 0 || function -> is_descriptor_only == 0 || function -> is_callable_descriptor) {
        return 0;
    }
    if (lm_trans_current_source_path == 0 || lm_trans_registry_path_is_predefined(lm_lmx_message_thread, lm_trans_current_source_path) == 0) {
        return 0;
    }
    if (lm_trans_registry_predefined_descriptor_site_is_hoisted(lm_lmx_message_thread, lm_trans_current_source_path, item -> node) == 0) {
        return 0;
    }
    if (lm_trans_registry_is_function_pointer_type_name(lm_lmx_message_thread, namespace_, function -> name)) {
        return 0;
    }
    return 1;
}

static int lm_trans_top_level_declare_function_compatible(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmTransTopLevelItem *item) {
    (void)lm_lmx_message_thread;
    int predefined_function;
    if (item == 0 || item -> function == 0) {
        return 1;
    }
    predefined_function = lm_trans_top_level_is_predefined_function_descriptor(lm_lmx_message_thread, namespace_, item);
    if (predefined_function) {
        if (item -> function -> is_sub == 0) {
            item->function->symbol_class = "function";
        }
        item->function->is_external = lm_trans_namespace_registry_source_path_n2_named_typed_value(lm_lmx_message_thread, namespace_, item -> function -> name, "fn.external", "class", "class", "value", "int") != 0;
    }
    else {
        if (lm_trans_registry_note_class_kind(lm_lmx_message_thread, item -> function -> name, item -> function -> symbol_class) != 0) {
            return 1;
        }
    }
    if (lm_trans_function_apply_thread_context_profile(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    if (lm_trans_namespace_declare_compatible(lm_lmx_message_thread, namespace_, item -> function -> name, item -> function -> symbol_class) != 0) {
        return 1;
    }
    if (lm_trans_namespace_set_callable_shape(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    if (item -> function -> is_thread_handler) {
        if (lm_trans_current_source_path != 0 && lm_trans_registry_path_is_predefined(lm_lmx_message_thread, lm_trans_current_source_path)) {
            fprintf(stderr, "trans L2 error: executable thread declarations are not allowed in predef modules; use import\n");
            return 1;
        }
        if (lm_trans_l2_conditional_import_depth > 0) {
            fprintf(stderr, "trans L2 error: thread declarations are not supported inside os/ifdef/guard\n");
            return 1;
        }
        if (lm_trans_namespace_add_thread_declaration(lm_lmx_message_thread, namespace_, item -> function) != 0) {
            return 1;
        }
    }
    if (lm_trans_top_level_declare_generated_return_class(lm_lmx_message_thread, namespace_, item -> function) != 0) {
        return 1;
    }
    return lm_trans_top_level_note_module_init_main(lm_lmx_message_thread, item -> function);
}

