static int lm_trans_l3_profile_enter_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    previous_depth = lm_trans_l3_profile_depth;
    if (lm_trans_frame_is_l3_level_receiver(lm_lmx_message_thread, frame)) {
        lm_trans_l3_profile_depth = previous_depth + 1;
    }
    return previous_depth;
}

