static int lm_trans_import_resolve_node(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *node, char *path, size_t path_size, const char *error_name) {
    (void)lm_lmx_message_thread;
    LmP0Text * path_value;
    char *candidate_name;
    const char *effective_error_name;
    int status;
    path_value = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (path_value == 0) {
        return 1;
    }
    if (node == 0 || node -> kind != LM_P0_NODE_ATOM || lm_trans_registry_literal_value(lm_lmx_message_thread, node -> as -> atom, path_value) == 0) {
        fprintf(stderr, "trans L2 import error: import path must be an atom/string\n");
        lm_trans_text_ref_destroy(&path_value);
        return 1;
    }
    candidate_name = lm_trans_text_copy_cstr(lm_lmx_message_thread, path_value);
    lm_trans_text_ref_destroy(&path_value);
    if (candidate_name == 0) {
        return 1;
    }
    status = lm_trans_registry_candidate_path(lm_lmx_message_thread, lm_trans_import_source_path(lm_lmx_message_thread), candidate_name, path, path_size);
    lm_own_delete(candidate_name, 0);
    if (status != 0) {
        effective_error_name = error_name;
        if (effective_error_name == 0) {
            effective_error_name = "import";
        }
        fprintf(stderr, "trans L2 import error: %s path is too long\n", effective_error_name);
        return 1;
    }
    return 0;
}

static int lm_trans_import_parse_document(struct LmMessageThread *lm_lmx_message_thread, const char *path, LmP0Document **out_document, const char *phase) {
    (void)lm_lmx_message_thread;
    const LmP0Diagnostic * diagnostic;
    const char *phase_name;
    int status;
    if (out_document == 0) {
        return 1;
    }
    out_document[0] = 0;
    status = lm_p0_parse_file(lm_lmx_message_thread, path, out_document);
    if (status == 0) {
        return 0;
    }
    diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, out_document[0]);
    if (diagnostic != 0) {
        phase_name = phase;
        if (phase_name == 0) {
            phase_name = "phase";
        }
        fprintf(stderr, "trans L2 import %s parse error %d at %zu:%zu in %s: %s\n", phase_name, diagnostic -> code, diagnostic -> line, diagnostic -> column, path, diagnostic -> message);
    }
    else {
        fprintf(stderr, "trans L2 import error: cannot read %s\n", path);
    }
    lm_p0_document_destroy(lm_lmx_message_thread, out_document[0]);
    out_document[0] = 0;
    return 1;
}

static int lm_trans_validate_l2_predef_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    char path[4096];
    int found;
    if (frame == 0) {
        return 1;
    }
    found = 0;
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (lm_trans_import_resolve_node(lm_lmx_message_thread, node, path, 4096U, "predef") != 0) {
                return 1;
            }
            if (lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm2") == 0) {
                fprintf(stderr, "trans L2 predef error: predef target must be an .lm2 module: %s\n", path);
                return 1;
            }
            found = 1;
        }
        field = field -> next;
    }
    if (found == 0) {
        fprintf(stderr, "trans L2 predef error: predef receiver expects at least one .lm2 path\n");
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static int lm_trans_declare_l2_predef_frame(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    if (lm_trans_validate_l2_predef_frame(lm_lmx_message_thread, frame) != 0) {
        return 1;
    }
    return lm_trans_declare_l2_import_frame(lm_lmx_message_thread, namespace_, frame);
}

static int lm_trans_declare_l2_import_root(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Node *root, int implicit_l2) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmTransTopLevelItem * item;
    int previous_depth;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    if (implicit_l2 && lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        return lm_trans_declare_l2_structure_import(lm_lmx_message_thread, namespace_, root -> as -> structure);
    }
    field = root -> as -> structure -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
                status = lm_trans_declare_l2_structure_import(lm_lmx_message_thread, namespace_, node -> as -> frame -> body);
                lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
                if (status != 0) {
                    return 1;
                }
            }
            else {
                item = lm_trans_top_level_item_lowered_new(lm_lmx_message_thread, node, namespace_);
                if (item == 0) {
                    return 1;
                }
                if (item -> declare != 0 && (item->declare)(lm_lmx_message_thread, namespace_, item) != 0) {
                    lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
                    return 1;
                }
                lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
            }
        }
        field = field -> next;
    }
    return 0;
}

static int lm_trans_emit_l2_import_root_prelude(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Node *root, int implicit_l2, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmTransTopLevelItem * item;
    int emitted;
    int previous_depth;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    if (implicit_l2 && lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        return lm_trans_emit_l2_structure_prelude(lm_lmx_message_thread, file, root -> as -> structure, namespace_);
    }
    emitted = 0;
    field = root -> as -> structure -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
                status = lm_trans_emit_l2_structure_prelude(lm_lmx_message_thread, file, node -> as -> frame -> body, namespace_);
                lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
            }
            else {
                item = lm_trans_top_level_item_lowered_new(lm_lmx_message_thread, node, namespace_);
                if (item == 0) {
                    return 1;
                }
                if (item -> emit_before_functions != 0) {
                    if (emitted && lm_trans_put(lm_lmx_message_thread, file, "\n") != 0) {
                        lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
                        return 1;
                    }
                    status = (item->emit_before_functions)(lm_lmx_message_thread, file, namespace_, item);
                }
                else {
                    status = 0;
                }
                if (item -> emits_top_level) {
                    emitted = 1;
                }
                lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
            }
            if (status != 0) {
                return 1;
            }
        }
        field = field -> next;
    }
    return 0;
}

