static int lm_trans_emit_l2_import_root_functions(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Node *root, int implicit_l2, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmTransTopLevelItem * item;
    int emitted;
    int previous_depth;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    if (implicit_l2 && lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        return lm_trans_emit_l2_structure_functions(lm_lmx_message_thread, file, root -> as -> structure, namespace_);
    }
    emitted = 0;
    field = root -> as -> structure -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                if (emitted && lm_trans_put(lm_lmx_message_thread, file, "\n") != 0) {
                    return 1;
                }
                previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
                status = lm_trans_emit_l2_structure_functions(lm_lmx_message_thread, file, node -> as -> frame -> body, namespace_);
                if (status == 0) {
                    status = lm_trans_validate_end_trailer(lm_lmx_message_thread, node -> as -> frame);
                }
                lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
                emitted = 1;
            }
            else {
                item = lm_trans_top_level_item_lowered_new(lm_lmx_message_thread, node, namespace_);
                if (item == 0) {
                    return 1;
                }
                if (item -> emit_function != 0) {
                    if (emitted && lm_trans_put(lm_lmx_message_thread, file, "\n") != 0) {
                        lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
                        return 1;
                    }
                    status = (item->emit_function)(lm_lmx_message_thread, file, namespace_, item);
                    emitted = 1;
                }
                else {
                    status = 0;
                }
                lm_trans_top_level_item_delete(lm_lmx_message_thread, item);
            }
            if (status != 0) {
                return 1;
            }
        }
        field = field -> next;
    }
    return 0;
}

static int lm_trans_declare_l2_import_path(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const char *path) {
    (void)lm_lmx_message_thread;
    LmP0Document * document;
    const char *previous_source_path;
    int loaded;
    int status;
    if (path == 0) {
        return 1;
    }
    if (lm_trans_l2_conditional_import_depth > 0) {
        fprintf(stderr, "trans L2 import error: import %s is not supported inside os/ifdef/guard\n", path);
        return 1;
    }
    if (lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm4")) {
        fprintf(stderr, "trans L2 import error: import does not accept legacy .lm4 registry targets; migrate the module to .lm2 and load it with predef: %s\n", path);
        return 1;
    }
    if (lm_trans_string_stack_has(lm_lmx_message_thread, lm_trans_declared_import_paths, path)) {
        return 0;
    }
    if (lm_trans_import_stack_note(lm_lmx_message_thread, lm_trans_declared_import_paths, path) != 0) {
        return 1;
    }
    if (lm_trans_registry_load_file_path(lm_lmx_message_thread, path, 1, &loaded) != 0) {
        return 1;
    }
    document = 0;
    if (lm_trans_import_parse_document(lm_lmx_message_thread, path, &document, "declare") != 0) {
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = path;
    status = lm_trans_declare_l2_import_root(lm_lmx_message_thread, namespace_, lm_p0_document_root(lm_lmx_message_thread, document), lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm2"));
    lm_trans_current_source_path = previous_source_path;
    if (status != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        return status;
    }
    if (lm_own_ptr_stack_push(lm_trans_declared_import_documents, document) != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        return 1;
    }
    return 0;
}

static int lm_trans_emit_l2_import_path_prelude(struct LmMessageThread *lm_lmx_message_thread, FILE *file, LmTransNamespace *namespace_, const char *path) {
    (void)lm_lmx_message_thread;
    LmP0Document * document;
    const char *previous_source_path;
    int loaded;
    int status;
    if (path == 0) {
        return 1;
    }
    if (lm_trans_string_stack_has(lm_lmx_message_thread, lm_trans_emitted_import_prelude_paths, path)) {
        return 0;
    }
    if (lm_trans_import_stack_note(lm_lmx_message_thread, lm_trans_emitted_import_prelude_paths, path) != 0) {
        return 1;
    }
    if (lm_trans_registry_load_file_path(lm_lmx_message_thread, path, 1, &loaded) != 0) {
        return 1;
    }
    document = 0;
    if (lm_trans_import_parse_document(lm_lmx_message_thread, path, &document, "prelude") != 0) {
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = path;
    status = lm_trans_emit_l2_import_root_prelude(lm_lmx_message_thread, file, lm_p0_document_root(lm_lmx_message_thread, document), lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm2"), namespace_);
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_prototypes(lm_lmx_message_thread, file, lm_p0_document_root(lm_lmx_message_thread, document), lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm2"), namespace_);
    }
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_after_prototypes(lm_lmx_message_thread, file, lm_p0_document_root(lm_lmx_message_thread, document), lm_trans_path_has_extension(lm_lmx_message_thread, path, ".lm2"), namespace_);
    }
    lm_trans_current_source_path = previous_source_path;
    lm_p0_document_destroy(lm_lmx_message_thread, document);
    return status;
}

