static int lm_trans_emit_l2_os_branch(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *branch, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int previous_emission_depth;
    int status;
    if (lm_trans_os_branch_looks_l2(lm_lmx_message_thread, branch -> body)) {
        previous_emission_depth = lm_trans_l2_conditional_emission_depth;
        lm_trans_l2_conditional_emission_depth = previous_emission_depth + 1;
        status = lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, branch -> body, 0, namespace_, 0);
        lm_trans_l2_conditional_emission_depth = previous_emission_depth;
        return status;
    }
    return lm_trans_emit_l1_structure(lm_lmx_message_thread, output, branch -> body);
}

static int lm_trans_emit_l2_os_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const LmP0Frame * branch;
    const char *condition;
    size_t group_id;
    size_t branch_id;
    int opened;
    int emitted_default;
    int status;
    if (frame == 0) {
        return 1;
    }
    opened = 0;
    emitted_default = 0;
    branch_id = 0U;
    if (lm_trans_typedef_projection_group_new(lm_lmx_message_thread, &group_id) != 0) {
        return 1;
    }
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind != LM_P0_NODE_FRAME) {
                fprintf(stderr, "trans L2 error: os receiver expects win/mac/unix/default frames\n");
                return 1;
            }
            branch = node -> as -> frame;
            if (lm_trans_text_equals(lm_lmx_message_thread, branch -> head, "default")) {
                if (emitted_default) {
                    fprintf(stderr, "trans L2 error: os receiver has duplicate default branch\n");
                    return 1;
                }
                emitted_default = 1;
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#else\n") != 0) {
                    return 1;
                }
            }
            else {
                condition = lm_trans_os_condition(lm_lmx_message_thread, branch -> head);
                if (condition == 0) {
                    fprintf(stderr, "trans L2 error: unknown os branch\n");
                    return 1;
                }
                if (emitted_default) {
                    fprintf(stderr, "trans L2 error: os default branch must be last\n");
                    return 1;
                }
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#elif ") != 0) {
                    return 1;
                }
                if (opened == 0 && lm_trans_put(lm_lmx_message_thread, output, "#if ") != 0) {
                    return 1;
                }
                if (lm_trans_put(lm_lmx_message_thread, output, condition) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
                    return 1;
                }
                opened = 1;
            }
            branch_id = branch_id + 1U;
            if (opened && lm_trans_typedef_projection_branch_enter(lm_lmx_message_thread, group_id, branch_id) != 0) {
                return 1;
            }
            status = lm_trans_emit_l2_os_branch(lm_lmx_message_thread, output, branch, namespace_);
            if (opened && lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread) != 0) {
                status = 1;
            }
            if (status != 0) {
                return 1;
            }
            if (lm_trans_validate_end_trailer(lm_lmx_message_thread, branch) != 0) {
                return 1;
            }
        }
        field = field -> next;
    }
    if (opened && lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static int lm_trans_emit_l2_ifdef_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const LmP0Frame * branch;
    LmP0Text * condition;
    size_t group_id;
    size_t branch_id;
    int opened;
    int emitted_default;
    int status;
    if (frame == 0) {
        return 1;
    }
    opened = 0;
    emitted_default = 0;
    branch_id = 0U;
    if (lm_trans_typedef_projection_group_new(lm_lmx_message_thread, &group_id) != 0) {
        return 1;
    }
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind != LM_P0_NODE_FRAME) {
                fprintf(stderr, "trans L2 error: ifdef receiver expects condition/default frames\n");
                return 1;
            }
            branch = node -> as -> frame;
            if (lm_trans_text_equals(lm_lmx_message_thread, branch -> head, "default")) {
                if (emitted_default) {
                    fprintf(stderr, "trans L2 error: ifdef receiver has duplicate default branch\n");
                    return 1;
                }
                emitted_default = 1;
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#else\n") != 0) {
                    return 1;
                }
            }
            else {
                if (emitted_default) {
                    fprintf(stderr, "trans L2 error: ifdef default branch must be last\n");
                    return 1;
                }
                condition = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
                if (condition == 0) {
                    return 1;
                }
                if (lm_trans_ifdef_condition_payload(lm_lmx_message_thread, branch -> head, condition) != 0) {
                    lm_trans_text_ref_destroy(&condition);
                    return 1;
                }
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#elif ") != 0) {
                    lm_trans_text_ref_destroy(&condition);
                    return 1;
                }
                if (opened == 0 && lm_trans_put(lm_lmx_message_thread, output, "#if ") != 0) {
                    lm_trans_text_ref_destroy(&condition);
                    return 1;
                }
                if (lm_trans_write_text(lm_lmx_message_thread, output, condition) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
                    lm_trans_text_ref_destroy(&condition);
                    return 1;
                }
                lm_trans_text_ref_destroy(&condition);
                opened = 1;
            }
            branch_id = branch_id + 1U;
            if (opened && lm_trans_typedef_projection_branch_enter(lm_lmx_message_thread, group_id, branch_id) != 0) {
                return 1;
            }
            status = lm_trans_emit_l2_os_branch(lm_lmx_message_thread, output, branch, namespace_);
            if (opened && lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread) != 0) {
                status = 1;
            }
            if (status != 0) {
                return 1;
            }
            if (lm_trans_validate_end_trailer(lm_lmx_message_thread, branch) != 0) {
                return 1;
            }
        }
        field = field -> next;
    }
    if (opened && lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static const LmP0Field * lm_trans_first_active_field(struct LmMessageThread *lm_lmx_message_thread, const LmP0Structure *body) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    field = 0;
    if (body != 0) {
        field = body -> first_field;
    }
    while (field != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, field -> value)) {
        field = field -> next;
    }
    return field;
}

static int lm_trans_emit_l2_wrapper_body(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Structure *body, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    if (lm_trans_os_branch_looks_l2(lm_lmx_message_thread, body)) {
        return lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, body, 0, namespace_, 0);
    }
    return lm_trans_emit_l1_structure(lm_lmx_message_thread, output, body);
}

static int lm_trans_declare_l2_wrapper_body(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Structure *body) {
    (void)lm_lmx_message_thread;
    if (lm_trans_os_branch_looks_l2(lm_lmx_message_thread, body)) {
        return lm_trans_declare_l2_structure_import(lm_lmx_message_thread, namespace_, body);
    }
    return 0;
}

static void lm_trans_structure_view_assign(struct LmMessageThread *lm_lmx_message_thread, LmP0Structure *target, const LmP0Structure *source) {
    (void)lm_lmx_message_thread;
    if (target == 0) {
        return;
    }
    if (source == 0) {
        target->first_field = 0;
        target->last_field = 0;
        target->field_count = 0U;
        return;
    }
    target->first_field = source -> first_field;
    target->last_field = source -> last_field;
    target->field_count = source -> field_count;
}

static int lm_trans_guard_body_from_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, LmP0Text *out_name, LmP0Structure *out_body) {
    (void)lm_lmx_message_thread;
    const LmP0Field * name_field;
    const LmP0Field * body_field;
    const LmP0Field * extra_field;
    if (frame == 0 || out_name == 0 || out_body == 0) {
        return 1;
    }
    name_field = lm_trans_first_active_field(lm_lmx_message_thread, frame -> body);
    if (name_field == 0 || name_field -> value == 0 || name_field -> value -> kind != LM_P0_NODE_ATOM) {
        fprintf(stderr, "trans L2 error: guard receiver expects guard name as first atom\n");
        return 1;
    }
    out_name->data = name_field -> value -> as -> atom -> data;
    out_name->length = name_field -> value -> as -> atom -> length;
    lm_trans_structure_view_assign(lm_lmx_message_thread, out_body, frame -> body);
    out_body->first_field = name_field -> next;
    body_field = lm_trans_first_active_field(lm_lmx_message_thread, out_body);
    if (body_field != 0 && body_field -> value != 0 && body_field -> value -> kind == LM_P0_NODE_STRUCTURE) {
        extra_field = body_field -> next;
        while (extra_field != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, extra_field -> value)) {
            extra_field = extra_field -> next;
        }
        if (extra_field == 0) {
            lm_trans_structure_view_assign(lm_lmx_message_thread, out_body, body_field -> value -> as -> structure);
        }
    }
    return 0;
}

static int lm_trans_declare_l2_guard_frame(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    LmP0Text * name;
    LmP0Structure * body;
    int previous_import_depth;
    int status;
    name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    body = lm_trans_p0_structure_view_new(lm_lmx_message_thread);
    if (name == 0 || body == 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    if (lm_trans_guard_body_from_frame(lm_lmx_message_thread, frame, name, body) != 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    previous_import_depth = lm_trans_l2_conditional_import_depth;
    lm_trans_l2_conditional_import_depth = previous_import_depth + 1;
    status = lm_trans_declare_l2_wrapper_body(lm_lmx_message_thread, namespace_, body);
    lm_trans_l2_conditional_import_depth = previous_import_depth;
    if (status == 0) {
        status = lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
    }
    lm_trans_text_ref_destroy(&name);
    lm_own_delete(body, 0);
    return status;
}

static int lm_trans_emit_l2_guard_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    LmP0Text * name;
    LmP0Structure * body;
    int previous_emission_depth;
    int status;
    name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    body = lm_trans_p0_structure_view_new(lm_lmx_message_thread);
    if (name == 0 || body == 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    if (lm_trans_guard_body_from_frame(lm_lmx_message_thread, frame, name, body) != 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, output, "#ifndef ") != 0 || lm_trans_emit_identifier(lm_lmx_message_thread, output, name) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n#define ") != 0 || lm_trans_emit_identifier(lm_lmx_message_thread, output, name) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    if (lm_trans_typedef_projection_conditional_enter(lm_lmx_message_thread) != 0) {
        lm_trans_text_ref_destroy(&name);
        lm_own_delete(body, 0);
        return 1;
    }
    previous_emission_depth = lm_trans_l2_conditional_emission_depth;
    lm_trans_l2_conditional_emission_depth = previous_emission_depth + 1;
    status = lm_trans_emit_l2_wrapper_body(lm_lmx_message_thread, output, body, namespace_);
    lm_trans_l2_conditional_emission_depth = previous_emission_depth;
    if (lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread) != 0) {
        status = 1;
    }
    if (status == 0) {
        if (lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
            status = 1;
        }
    }
    if (status == 0 && lm_trans_validate_end_trailer(lm_lmx_message_thread, frame) != 0) {
        status = 1;
    }
    lm_trans_text_ref_destroy(&name);
    lm_own_delete(body, 0);
    return status;
}

static int lm_trans_declare_l2_extern_c_frame(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (frame == 0) {
        return 1;
    }
    previous_depth = lm_trans_module_init_unsupported_wrapper_depth;
    lm_trans_module_init_unsupported_wrapper_depth = previous_depth + 1;
    status = lm_trans_declare_l2_wrapper_body(lm_lmx_message_thread, namespace_, frame -> body);
    lm_trans_module_init_unsupported_wrapper_depth = previous_depth;
    if (status != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static int lm_trans_emit_l2_extern_c_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (frame == 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, output, "#ifdef __cplusplus\nextern \"C\" {\n#endif\n") != 0) {
        return 1;
    }
    previous_depth = lm_trans_module_init_unsupported_wrapper_depth;
    lm_trans_module_init_unsupported_wrapper_depth = previous_depth + 1;
    status = lm_trans_emit_l2_wrapper_body(lm_lmx_message_thread, output, frame -> body, namespace_);
    lm_trans_module_init_unsupported_wrapper_depth = previous_depth;
    if (status != 0) {
        return 1;
    }
    if (lm_trans_put(lm_lmx_message_thread, output, "#ifdef __cplusplus\n}\n#endif\n") != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static int lm_trans_declare_l2_registry_os_node(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Node *node) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (node == 0) {
        return 0;
    }
    if (node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
        previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
        status = lm_trans_declare_l2_conditional_structure_import(lm_lmx_message_thread, namespace_, node -> as -> frame -> body);
        if (status == 0) {
            status = lm_trans_validate_end_trailer(lm_lmx_message_thread, node -> as -> frame);
        }
        lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
        return status;
    }
    if (node -> kind == LM_P0_NODE_STRUCTURE && lm_trans_os_branch_looks_l2(lm_lmx_message_thread, node -> as -> structure)) {
        return lm_trans_declare_l2_conditional_structure_import(lm_lmx_message_thread, namespace_, node -> as -> structure);
    }
    return 0;
}

static int lm_trans_registry_condition_view_row_matches(struct LmMessageThread *lm_lmx_message_thread, const LmRegistryViewRow *row, const char *table_name) {
    (void)lm_lmx_message_thread;
    size_t table_length;
    size_t row_table_length;
    if (row == 0 || row -> table == 0 || table_name == 0) {
        return 0;
    }
    if (strcmp(row -> table, table_name) == 0) {
        return 1;
    }
    table_length = strlen(table_name);
    row_table_length = strlen(row -> table);
    if (row_table_length != table_length + 5U || memcmp(row -> table, table_name, table_length) != 0) {
        return 0;
    }
    return strcmp(row -> table + table_length, ".body") == 0;
}

static size_t lm_trans_registry_condition_row_count(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *table_name, int *out_view_rows, int *out_present) {
    (void)lm_lmx_message_thread;
    const LmRegistryView * view;
    const LmRegistryViewRow * view_row;
    const LmOwnPtrStack * rows;
    LmTransRegistryFact * row;
    LmP0Text * table_text;
    size_t fact_count;
    size_t count;
    size_t i;
    if (out_view_rows != 0) {
        out_view_rows[0] = 0;
    }
    if (out_present != 0) {
        out_present[0] = 0;
    }
    if (table_name == 0 || out_view_rows == 0 || out_present == 0) {
        return 0U;
    }
    view = lm_trans_namespace_registry_view(lm_lmx_message_thread, namespace_);
    if (view != 0) {
        out_view_rows[0] = 1;
        count = 0U;
        fact_count = lm_registry_view_fact_count(lm_lmx_message_thread, view);
        i = 0U;
        while (i < fact_count) {
            view_row = lm_registry_view_fact_at(lm_lmx_message_thread, view, i);
            if (lm_trans_registry_condition_view_row_matches(lm_lmx_message_thread, view_row, table_name) != 0) {
                out_present[0] = 1;
                if (view_row -> key != 0 && view_row -> payload_node != 0) {
                    count = count + 1U;
                }
            }
            i = i + 1U;
        }
        return count;
    }
    table_text = lm_trans_text_from_cstr(lm_lmx_message_thread, table_name);
    if (table_text == 0) {
        return 0U;
    }
    rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, table_text, "row");
    lm_trans_text_ref_destroy(&table_text);
    if (rows == 0) {
        return 0U;
    }
    out_present[0] = 1;
    count = 0U;
    i = 0U;
    while (i < rows -> count) {
        row = lm_own_ptr_stack_at(rows, i);
        if (row != 0 && row -> key != 0 && row -> payload_node != 0) {
            count = count + 1U;
        }
        i = i + 1U;
    }
    return count;
}

static int lm_trans_registry_condition_row_at(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *table_name, size_t index, int view_rows, const char **out_name, const LmP0Node **out_body) {
    (void)lm_lmx_message_thread;
    const LmRegistryView * view;
    const LmRegistryViewRow * view_row;
    const LmOwnPtrStack * rows;
    LmTransRegistryFact * row;
    const LmTransRegistryFact * facade_row;
    const LmTableCell * source_key_cell;
    const LmTableCell * source_node_cell;
    LmP0Text * table_text;
    size_t fact_count;
    size_t selected_index;
    size_t i;
    if (out_name != 0) {
        out_name[0] = 0;
    }
    if (out_body != 0) {
        out_body[0] = 0;
    }
    if (table_name == 0 || out_name == 0 || out_body == 0) {
        return 0;
    }
    if (view_rows != 0) {
        view = lm_trans_namespace_registry_view(lm_lmx_message_thread, namespace_);
        fact_count = lm_registry_view_fact_count(lm_lmx_message_thread, view);
        selected_index = 0U;
        i = 0U;
        while (i < fact_count) {
            view_row = lm_registry_view_fact_at(lm_lmx_message_thread, view, i);
            if (lm_trans_registry_condition_view_row_matches(lm_lmx_message_thread, view_row, table_name) != 0 && view_row -> key != 0 && view_row -> payload_node != 0) {
                if (selected_index == index) {
                    out_name[0] = view_row -> key;
                    out_body[0] = view_row -> payload_node;
                    facade_row = ((const LmTransRegistryFact *)view_row -> source);
                    if (strcmp(view_row -> table, table_name) == 0) {
                        out_body[0] = lm_trans_registry_source_n2_node(lm_lmx_message_thread, namespace_, table_name, "class", "body", facade_row);
                    }
                    source_key_cell = 0;
                    source_node_cell = lm_trans_registry_source_path_typed_node_cell(lm_lmx_message_thread, namespace_, view_row -> table, "class", "class", "node", "body", facade_row, &source_key_cell);
                    if (source_node_cell != 0 && source_key_cell != 0 && source_key_cell -> value != 0 && lm_trans_registry_view_is_selected(lm_lmx_message_thread) != 0) {
                        out_name[0] = source_key_cell -> value;
                        out_body[0] = ((const LmP0Node *)source_node_cell -> node);
                    }
                    return 1;
                }
                selected_index = selected_index + 1U;
            }
            i = i + 1U;
        }
        return 0;
    }
    table_text = lm_trans_text_from_cstr(lm_lmx_message_thread, table_name);
    if (table_text == 0) {
        return 0;
    }
    rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, table_text, "row");
    lm_trans_text_ref_destroy(&table_text);
    selected_index = 0U;
    i = 0U;
    while (rows != 0 && i < rows -> count) {
        row = lm_own_ptr_stack_at(rows, i);
        if (row != 0 && row -> key != 0 && row -> payload_node != 0) {
            if (selected_index == index) {
                out_name[0] = row -> key;
                out_body[0] = row -> payload_node;
                return 1;
            }
            selected_index = selected_index + 1U;
        }
        i = i + 1U;
    }
    return 0;
}

static int lm_trans_declare_l2_registry_os_table(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t row_count;
    const LmP0Node * body;
    const char *row_name;
    LmP0Text * branch_name;
    const char *condition;
    int emitted_default;
    int emitted;
    int present;
    int view_rows;
    emitted_default = 0;
    emitted = 0;
    row_count = lm_trans_registry_condition_row_count(lm_lmx_message_thread, namespace_, "os", &view_rows, &present);
    if (row_count == 0U && present == 0) {
        return 0;
    }
    if (row_count == 0U) {
        fprintf(stderr, "trans L2 error: atom os receiver expects table os with node body cells\n");
        return 1;
    }
    branch_name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (branch_name == 0) {
        return 1;
    }
    i = 0U;
    while (i < row_count) {
        if (lm_trans_registry_condition_row_at(lm_lmx_message_thread, namespace_, "os", i, view_rows, &row_name, &body) == 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        lm_trans_text_assign_cstr(lm_lmx_message_thread, branch_name, row_name);
        if (lm_trans_text_equals(lm_lmx_message_thread, branch_name, "default")) {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry os table has duplicate default branch\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            emitted_default = 1;
        }
        else {
            condition = lm_trans_os_condition(lm_lmx_message_thread, branch_name);
            if (condition == 0) {
                fprintf(stderr, "trans L2 error: registry os table has unknown branch %s\n", row_name);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry os default branch must be last\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
        }
        if (lm_trans_declare_l2_registry_os_node(lm_lmx_message_thread, namespace_, body) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        emitted = 1;
        i = i + 1U;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L2 error: atom os receiver expects table os with node body cells\n");
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    lm_trans_text_ref_destroy(&branch_name);
    return 0;
}

static int lm_trans_declare_l2_registry_ifdef_table(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t row_count;
    const LmP0Node * body;
    const char *row_name;
    LmP0Text * branch_name;
    LmP0Text * condition;
    int emitted_default;
    int emitted;
    int present;
    int view_rows;
    emitted_default = 0;
    emitted = 0;
    row_count = lm_trans_registry_condition_row_count(lm_lmx_message_thread, namespace_, "ifdef", &view_rows, &present);
    if (row_count == 0U && present == 0) {
        return 0;
    }
    if (row_count == 0U) {
        fprintf(stderr, "trans L2 error: atom ifdef receiver expects table ifdef with node body cells\n");
        return 1;
    }
    branch_name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (branch_name == 0) {
        return 1;
    }
    i = 0U;
    while (i < row_count) {
        if (lm_trans_registry_condition_row_at(lm_lmx_message_thread, namespace_, "ifdef", i, view_rows, &row_name, &body) == 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        lm_trans_text_assign_cstr(lm_lmx_message_thread, branch_name, row_name);
        if (lm_trans_text_equals(lm_lmx_message_thread, branch_name, "default")) {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry ifdef table has duplicate default branch\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            emitted_default = 1;
        }
        else {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry ifdef default branch must be last\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            condition = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
            if (condition == 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (lm_trans_ifdef_condition_payload(lm_lmx_message_thread, branch_name, condition) != 0) {
                lm_trans_text_ref_destroy(&condition);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            lm_trans_text_ref_destroy(&condition);
        }
        if (lm_trans_declare_l2_registry_os_node(lm_lmx_message_thread, namespace_, body) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        emitted = 1;
        i = i + 1U;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L2 error: atom ifdef receiver expects table ifdef with node body cells\n");
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    lm_trans_text_ref_destroy(&branch_name);
    return 0;
}

static int lm_trans_emit_l2_registry_os_node(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Node *node, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (node == 0) {
        return 0;
    }
    if (node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
        previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
        status = lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, node -> as -> frame -> body, node -> as -> frame, namespace_, 0);
        lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
        return status;
    }
    if (node -> kind == LM_P0_NODE_STRUCTURE && lm_trans_os_branch_looks_l2(lm_lmx_message_thread, node -> as -> structure)) {
        return lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, node -> as -> structure, 0, namespace_, 0);
    }
    return lm_trans_emit_l1_node(lm_lmx_message_thread, output, node);
}

static int lm_trans_emit_l2_registry_conditional_node(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Node *node, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int previous_emission_depth;
    int status;
    previous_emission_depth = lm_trans_l2_conditional_emission_depth;
    lm_trans_l2_conditional_emission_depth = previous_emission_depth + 1;
    status = lm_trans_emit_l2_registry_os_node(lm_lmx_message_thread, output, node, namespace_);
    lm_trans_l2_conditional_emission_depth = previous_emission_depth;
    return status;
}

static int lm_trans_l4_payload_structure_looks_bare_l2(struct LmMessageThread *lm_lmx_message_thread, const LmP0Structure *body) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    int found;
    if (body == 0) {
        return 0;
    }
    found = 0;
    field = body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind == LM_P0_NODE_ATOM) {
                return 0;
            }
            if (node -> kind == LM_P0_NODE_FRAME) {
                if (lm_trans_frame_is_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame) || lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame) || lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "include") || lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "os") || lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "ifdef") || lm_trans_end_frame_targets_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                    return 0;
                }
                found = 1;
            }
            else {
                if (node -> kind == LM_P0_NODE_STRUCTURE) {
                    found = 1;
                }
                else {
                    return 0;
                }
            }
        }
        field = field -> next;
    }
    return found;
}

static int lm_trans_emit_l4_payload_import_document(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const char *payload_path, const LmP0Node *root, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const char *previous_source_path;
    FILE * prelude_file;
    int loaded;
    int status;
    if (output == 0 || payload_path == 0 || root == 0 || namespace_ == 0) {
        return 1;
    }
    if (lm_trans_path_has_extension(lm_lmx_message_thread, payload_path, ".lm2") == 0) {
        return lm_trans_emit_l4_payload_node(lm_lmx_message_thread, output, root, namespace_);
    }
    if (lm_trans_registry_load_file_path(lm_lmx_message_thread, payload_path, 1, &loaded) != 0) {
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = payload_path;
    status = lm_trans_declare_l2_import_root(lm_lmx_message_thread, namespace_, root, 1);
    prelude_file = lm_trans_prelude_file(lm_lmx_message_thread, output);
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_prelude(lm_lmx_message_thread, prelude_file, root, 1, namespace_);
    }
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_prototypes(lm_lmx_message_thread, prelude_file, root, 1, namespace_);
    }
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_after_prototypes(lm_lmx_message_thread, prelude_file, root, 1, namespace_);
    }
    if (status == 0) {
        status = lm_trans_emit_l2_import_root_functions(lm_lmx_message_thread, output, root, 1, namespace_);
    }
    lm_trans_current_source_path = previous_source_path;
    return status;
}

static int lm_trans_emit_l4_payload_import_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const LmP0Diagnostic * diagnostic;
    LmP0Document * document;
    LmP0Text * path_value;
    char *candidate_name;
    char payload_path[4096];
    int emitted;
    int status;
    if (frame == 0) {
        return 1;
    }
    path_value = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (path_value == 0) {
        return 1;
    }
    field = frame -> body -> first_field;
    emitted = 0;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node == 0 || node -> kind != LM_P0_NODE_ATOM || lm_trans_registry_literal_value(lm_lmx_message_thread, node -> as -> atom, path_value) == 0) {
                fprintf(stderr, "trans L4 unit error: unit.payload import path must be an atom/string\n");
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            candidate_name = lm_trans_text_copy_cstr(lm_lmx_message_thread, path_value);
            if (candidate_name == 0) {
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            if (lm_trans_registry_candidate_path(lm_lmx_message_thread, lm_trans_registry -> source_path, candidate_name, payload_path, 4096U) != 0) {
                lm_own_delete(candidate_name, 0);
                fprintf(stderr, "trans L4 unit error: unit.payload import path is too long\n");
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            lm_own_delete(candidate_name, 0);
            if (lm_trans_path_has_extension(lm_lmx_message_thread, payload_path, ".lm4") != 0) {
                fprintf(stderr, "trans L4 unit error: unit.payload import does not accept .lm4 modules: %s\n", payload_path);
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            document = 0;
            status = lm_p0_parse_file(lm_lmx_message_thread, payload_path, &document);
            if (status != 0) {
                diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, document);
                if (diagnostic != 0) {
                    fprintf(stderr, "trans L4 unit import parse error %d at %zu:%zu in %s: %s\n", diagnostic -> code, diagnostic -> line, diagnostic -> column, payload_path, diagnostic -> message);
                }
                if (diagnostic == 0) {
                    fprintf(stderr, "trans L4 unit error: cannot read unit.payload import %s\n", payload_path);
                }
                lm_p0_document_destroy(lm_lmx_message_thread, document);
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            if (lm_trans_emit_l4_payload_import_document(lm_lmx_message_thread, output, payload_path, lm_p0_document_root(lm_lmx_message_thread, document), namespace_) != 0) {
                lm_p0_document_destroy(lm_lmx_message_thread, document);
                lm_trans_text_ref_destroy(&path_value);
                return 1;
            }
            lm_p0_document_destroy(lm_lmx_message_thread, document);
            emitted = 1;
        }
        field = field -> next;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L4 unit error: unit.payload import receiver expects at least one path\n");
        lm_trans_text_ref_destroy(&path_value);
        return 1;
    }
    lm_trans_text_ref_destroy(&path_value);
    return 0;
}

static int lm_trans_l4_payload_receiver_import(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    return lm_trans_emit_l4_payload_import_frame(lm_lmx_message_thread, output, frame, namespace_);
}

static int lm_trans_l4_payload_receiver_level(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (frame == 0) {
        return 1;
    }
    previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, frame);
    status = lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, frame -> body, frame, namespace_, 0);
    lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
    return status;
}

static int lm_trans_l4_payload_pointer_binding_push(struct LmMessageThread *lm_lmx_message_thread, LmOwnPtrStack *bindings, const char *head, const char *receiver_type, LmTransL4PayloadFrameHandler handler) {
    (void)lm_lmx_message_thread;
    LmTransL4PayloadPointerBinding * binding;
    if (bindings == 0 || head == 0 || receiver_type == 0 || handler == 0) {
        return 1;
    }
    binding = lm_own_new_zero(sizeof(binding[0]));
    if (binding == 0) {
        return 1;
    }
    binding->head = head;
    binding->receiver_type = receiver_type;
    binding->handler = handler;
    if (lm_own_ptr_stack_push(bindings, binding) != 0) {
        lm_own_delete(binding, 0);
        return 1;
    }
    return 0;
}

static int lm_trans_l4_payload_pointer_bindings_init(struct LmMessageThread *lm_lmx_message_thread) {
    (void)lm_lmx_message_thread;
    LmOwnPtrStack * bindings;
    if (lm_trans_registry == 0) {
        return 1;
    }
    if (lm_trans_registry -> l4_payload_pointer_bindings != 0) {
        return 0;
    }
    bindings = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    if (bindings == 0) {
        return 1;
    }
    if (lm_trans_l4_payload_pointer_binding_push(lm_lmx_message_thread, bindings, "import", "l4.payload", lm_trans_l4_payload_receiver_import) != 0 || lm_trans_l4_payload_pointer_binding_push(lm_lmx_message_thread, bindings, "L2", "l4.payload", lm_trans_l4_payload_receiver_level) != 0 || lm_trans_l4_payload_pointer_binding_push(lm_lmx_message_thread, bindings, "L3", "l4.payload", lm_trans_l4_payload_receiver_level) != 0) {
        lm_trans_ptr_stack_delete(&bindings);
        return 1;
    }
    lm_trans_registry->l4_payload_pointer_bindings = bindings;
    return 0;
}

static void lm_trans_l4_payload_pointer_bindings_destroy(struct LmMessageThread *lm_lmx_message_thread) {
    (void)lm_lmx_message_thread;
    if (lm_trans_registry != 0) {
        lm_trans_ptr_stack_delete(&lm_trans_registry -> l4_payload_pointer_bindings);
    }
}

static const LmTransL4PayloadPointerBinding * lm_trans_l4_payload_pointer_binding_find(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *head) {
    (void)lm_lmx_message_thread;
    size_t i;
    const LmOwnPtrStack * bindings;
    const LmTransL4PayloadPointerBinding * binding;
    if (head == 0 || lm_trans_registry == 0 || lm_trans_registry -> l4_payload_pointer_bindings == 0) {
        return 0;
    }
    bindings = lm_trans_registry -> l4_payload_pointer_bindings;
    i = 0U;
    while (i < bindings -> count) {
        binding = lm_own_ptr_stack_at(bindings, i);
        if (binding != 0 && lm_trans_text_equals(lm_lmx_message_thread, head, binding -> head)) {
            return binding;
        }
        i = i + 1U;
    }
    return 0;
}

static int lm_trans_l4_payload_frame_handler_resolve(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *head, LmTransL4PayloadFrameHandler *out) {
    (void)lm_lmx_message_thread;
    const char *receiver_type;
    const LmTransL4PayloadPointerBinding * binding;
    if (head == 0 || out == 0) {
        return 1;
    }
    out[0] = 0;
    receiver_type = lm_trans_l4_namespace_receiver_type_value(lm_lmx_message_thread, head, "namespace.l4.payload");
    if (receiver_type == 0) {
        return 0;
    }
    binding = lm_trans_l4_payload_pointer_binding_find(lm_lmx_message_thread, head);
    if (binding == 0) {
        fprintf(stderr, "trans registry inconsistency: namespace.l4.payload[\"%.*s\"] has no direct L4 payload pointer binding\n", (((int)head -> length)), head -> data);
        return 1;
    }
    if (strcmp(receiver_type, binding -> receiver_type) != 0) {
        fprintf(stderr, "trans registry inconsistency: namespace.l4.payload[\"%.*s\"] has receiver marker %s, expected %s\n", (((int)head -> length)), head -> data, receiver_type, binding -> receiver_type);
        return 1;
    }
    out[0] = binding -> handler;
    return 0;
}

static int lm_trans_emit_l4_payload_node(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Node *node, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    LmTransL4PayloadFrameHandler frame_handler;
    if (node == 0) {
        return 0;
    }
    if (node -> kind == LM_P0_NODE_FRAME) {
        if (lm_trans_l4_payload_frame_handler_resolve(lm_lmx_message_thread, node -> as -> frame -> head, &frame_handler) != 0) {
            return 1;
        }
        if (frame_handler != 0) {
            return frame_handler(lm_lmx_message_thread, output, node -> as -> frame, namespace_);
        }
    }
    if (node -> kind == LM_P0_NODE_STRUCTURE && lm_trans_l4_payload_structure_looks_bare_l2(lm_lmx_message_thread, node -> as -> structure)) {
        return lm_trans_emit_l2_structure_with_namespace(lm_lmx_message_thread, output, node -> as -> structure, 0, namespace_, 0);
    }
    return lm_trans_emit_l1_node(lm_lmx_message_thread, output, node);
}

static int lm_trans_emit_l2_registry_os_table(struct LmMessageThread *lm_lmx_message_thread, FILE *output, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t row_count;
    const LmP0Node * body;
    const char *row_name;
    LmP0Text * branch_name;
    const char *condition;
    size_t group_id;
    int opened;
    int emitted_default;
    int emitted;
    int present;
    int view_rows;
    opened = 0;
    emitted_default = 0;
    emitted = 0;
    row_count = lm_trans_registry_condition_row_count(lm_lmx_message_thread, namespace_, "os", &view_rows, &present);
    if (row_count == 0U && present == 0) {
        return 0;
    }
    if (row_count == 0U) {
        fprintf(stderr, "trans L2 error: atom os receiver expects table os with node body cells\n");
        return 1;
    }
    branch_name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (branch_name == 0) {
        return 1;
    }
    if (lm_trans_typedef_projection_group_new(lm_lmx_message_thread, &group_id) != 0) {
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    i = 0U;
    while (i < row_count) {
        if (lm_trans_registry_condition_row_at(lm_lmx_message_thread, namespace_, "os", i, view_rows, &row_name, &body) == 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        lm_trans_text_assign_cstr(lm_lmx_message_thread, branch_name, row_name);
        if (lm_trans_text_equals(lm_lmx_message_thread, branch_name, "default")) {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry os table has duplicate default branch\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            emitted_default = 1;
            if (opened && lm_trans_put(lm_lmx_message_thread, output, "#else\n") != 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
        }
        else {
            condition = lm_trans_os_condition(lm_lmx_message_thread, branch_name);
            if (condition == 0) {
                fprintf(stderr, "trans L2 error: registry os table has unknown branch %s\n", row_name);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry os default branch must be last\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (opened && lm_trans_put(lm_lmx_message_thread, output, "#elif ") != 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (opened == 0 && lm_trans_put(lm_lmx_message_thread, output, "#if ") != 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (lm_trans_put(lm_lmx_message_thread, output, condition) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            opened = 1;
        }
        if (opened && lm_trans_typedef_projection_branch_enter(lm_lmx_message_thread, group_id, i + 1U) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        if (lm_trans_emit_l2_registry_conditional_node(lm_lmx_message_thread, output, body, namespace_) != 0) {
            if (opened) {
                lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread);
            }
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        if (opened && lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        emitted = 1;
        i = i + 1U;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L2 error: atom os receiver expects table os with node body cells\n");
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    if (opened && lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    lm_trans_text_ref_destroy(&branch_name);
    return 0;
}

static int lm_trans_emit_l2_registry_ifdef_table(struct LmMessageThread *lm_lmx_message_thread, FILE *output, LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t row_count;
    const LmP0Node * body;
    const char *row_name;
    LmP0Text * branch_name;
    LmP0Text * condition;
    size_t group_id;
    int opened;
    int emitted_default;
    int emitted;
    int present;
    int view_rows;
    opened = 0;
    emitted_default = 0;
    emitted = 0;
    row_count = lm_trans_registry_condition_row_count(lm_lmx_message_thread, namespace_, "ifdef", &view_rows, &present);
    if (row_count == 0U && present == 0) {
        return 0;
    }
    if (row_count == 0U) {
        fprintf(stderr, "trans L2 error: atom ifdef receiver expects table ifdef with node body cells\n");
        return 1;
    }
    branch_name = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (branch_name == 0) {
        return 1;
    }
    if (lm_trans_typedef_projection_group_new(lm_lmx_message_thread, &group_id) != 0) {
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    i = 0U;
    while (i < row_count) {
        if (lm_trans_registry_condition_row_at(lm_lmx_message_thread, namespace_, "ifdef", i, view_rows, &row_name, &body) == 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        lm_trans_text_assign_cstr(lm_lmx_message_thread, branch_name, row_name);
        if (lm_trans_text_equals(lm_lmx_message_thread, branch_name, "default")) {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry ifdef table has duplicate default branch\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            emitted_default = 1;
            if (opened && lm_trans_put(lm_lmx_message_thread, output, "#else\n") != 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
        }
        else {
            if (emitted_default) {
                fprintf(stderr, "trans L2 error: registry ifdef default branch must be last\n");
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            condition = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
            if (condition == 0) {
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (lm_trans_ifdef_condition_payload(lm_lmx_message_thread, branch_name, condition) != 0) {
                lm_trans_text_ref_destroy(&condition);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (opened && lm_trans_put(lm_lmx_message_thread, output, "#elif ") != 0) {
                lm_trans_text_ref_destroy(&condition);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (opened == 0 && lm_trans_put(lm_lmx_message_thread, output, "#if ") != 0) {
                lm_trans_text_ref_destroy(&condition);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            if (lm_trans_write_text(lm_lmx_message_thread, output, condition) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
                lm_trans_text_ref_destroy(&condition);
                lm_trans_text_ref_destroy(&branch_name);
                return 1;
            }
            lm_trans_text_ref_destroy(&condition);
            opened = 1;
        }
        if (opened && lm_trans_typedef_projection_branch_enter(lm_lmx_message_thread, group_id, i + 1U) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        if (lm_trans_emit_l2_registry_conditional_node(lm_lmx_message_thread, output, body, namespace_) != 0) {
            if (opened) {
                lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread);
            }
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        if (opened && lm_trans_typedef_projection_conditional_leave(lm_lmx_message_thread) != 0) {
            lm_trans_text_ref_destroy(&branch_name);
            return 1;
        }
        emitted = 1;
        i = i + 1U;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L2 error: atom ifdef receiver expects table ifdef with node body cells\n");
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    if (opened && lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
        lm_trans_text_ref_destroy(&branch_name);
        return 1;
    }
    lm_trans_text_ref_destroy(&branch_name);
    return 0;
}

static int lm_trans_emit_l1_os_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const LmP0Frame * branch;
    const char *condition;
    int opened;
    int emitted_default;
    if (frame == 0) {
        return 1;
    }
    opened = 0;
    emitted_default = 0;
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind != LM_P0_NODE_FRAME) {
                fprintf(stderr, "trans L1 error: os receiver expects win/mac/unix/default frames\n");
                return 1;
            }
            branch = node -> as -> frame;
            if (lm_trans_text_equals(lm_lmx_message_thread, branch -> head, "default")) {
                if (emitted_default) {
                    fprintf(stderr, "trans L1 error: os receiver has duplicate default branch\n");
                    return 1;
                }
                emitted_default = 1;
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#else\n") != 0) {
                    return 1;
                }
            }
            else {
                condition = lm_trans_os_condition(lm_lmx_message_thread, branch -> head);
                if (condition == 0) {
                    fprintf(stderr, "trans L1 error: unknown os branch\n");
                    return 1;
                }
                if (emitted_default) {
                    fprintf(stderr, "trans L1 error: os default branch must be last\n");
                    return 1;
                }
                if (opened && lm_trans_put(lm_lmx_message_thread, output, "#elif ") != 0) {
                    return 1;
                }
                if (opened == 0 && lm_trans_put(lm_lmx_message_thread, output, "#if ") != 0) {
                    return 1;
                }
                if (lm_trans_put(lm_lmx_message_thread, output, condition) != 0 || lm_trans_put(lm_lmx_message_thread, output, "\n") != 0) {
                    return 1;
                }
                opened = 1;
            }
            if (lm_trans_emit_l1_structure(lm_lmx_message_thread, output, branch -> body) != 0) {
                return 1;
            }
            if (lm_trans_validate_end_trailer(lm_lmx_message_thread, branch) != 0) {
                return 1;
            }
        }
        field = field -> next;
    }
    if (opened && lm_trans_put(lm_lmx_message_thread, output, "#endif\n") != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

