static int lm_trans_emit_l1_include_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *frame) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmP0Text * payload;
    int emitted;
    if (frame == 0) {
        return 1;
    }
    payload = lm_trans_text_from_cstr(lm_lmx_message_thread, "");
    if (payload == 0) {
        return 1;
    }
    emitted = 0;
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind != LM_P0_NODE_ATOM || lm_trans_inline_string_payload(lm_lmx_message_thread, node -> as -> atom, payload, 0) == 0 || payload -> length == 0U) {
                fprintf(stderr, "trans L1 error: include receiver expects string header atoms\n");
                lm_trans_text_ref_destroy(&payload);
                return 1;
            }
            if (lm_trans_emit_l1_include_target_text(lm_lmx_message_thread, output, payload -> data, payload -> length) != 0) {
                lm_trans_text_ref_destroy(&payload);
                return 1;
            }
            emitted = 1;
        }
        field = field -> next;
    }
    if (emitted == 0) {
        fprintf(stderr, "trans L1 error: include receiver expects at least one header\n");
        lm_trans_text_ref_destroy(&payload);
        return 1;
    }
    lm_trans_text_ref_destroy(&payload);
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static int lm_trans_emit_l1_node(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Node *node) {
    (void)lm_lmx_message_thread;
    int previous_depth;
    int status;
    if (lm_trans_node_is_ignored(lm_lmx_message_thread, node)) {
        return 0;
    }
    if (node -> kind == LM_P0_NODE_ATOM) {
        if (lm_trans_emit_l1_payload(lm_lmx_message_thread, output, node -> as -> atom) != 0) {
            return 1;
        }
        return lm_trans_write_all(lm_lmx_message_thread, output, "\n", 1U);
    }
    if (node -> kind == LM_P0_NODE_STRUCTURE) {
        return lm_trans_emit_l1_structure(lm_lmx_message_thread, output, node -> as -> structure);
    }
    if (node -> kind == LM_P0_NODE_FRAME) {
        if (lm_trans_frame_is_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame)) {
            return lm_trans_emit_l1_frame(lm_lmx_message_thread, output, node -> as -> frame);
        }
        if (lm_trans_frame_is_l2_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
            previous_depth = lm_trans_module_init_unsupported_wrapper_depth;
            lm_trans_module_init_unsupported_wrapper_depth = previous_depth + 1;
            status = lm_trans_emit_l2_frame(lm_lmx_message_thread, output, node -> as -> frame);
            lm_trans_module_init_unsupported_wrapper_depth = previous_depth;
            return status;
        }
        if (lm_trans_frame_is_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
            previous_depth = lm_trans_module_init_unsupported_wrapper_depth;
            lm_trans_module_init_unsupported_wrapper_depth = previous_depth + 1;
            status = lm_trans_emit_l3_frame(lm_lmx_message_thread, output, node -> as -> frame);
            lm_trans_module_init_unsupported_wrapper_depth = previous_depth;
            return status;
        }
        if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "os")) {
            return lm_trans_emit_l1_os_frame(lm_lmx_message_thread, output, node -> as -> frame);
        }
        if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "ifdef")) {
            return lm_trans_emit_l1_ifdef_frame(lm_lmx_message_thread, output, node -> as -> frame);
        }
        if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "include")) {
            return lm_trans_emit_l1_include_frame(lm_lmx_message_thread, output, node -> as -> frame);
        }
        if (lm_trans_end_frame_targets_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame)) {
            return 0;
        }
        fprintf(stderr, "trans error: unknown translator receiver inside L1\n");
        return 1;
    }
    return 0;
}

static int lm_trans_emit_l1_frame(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *l1) {
    (void)lm_lmx_message_thread;
    if (l1 == 0) {
        return 1;
    }
    if (lm_trans_emit_l1_structure(lm_lmx_message_thread, output, l1 -> body) != 0) {
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, l1);
}

static int lm_trans_emit_l1_body(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Frame *l1, int *emitted) {
    (void)lm_lmx_message_thread;
    if (lm_trans_emit_l1_frame(lm_lmx_message_thread, output, l1) != 0) {
        return 1;
    }
    if (emitted != 0) {
        emitted[0] = 1;
    }
    return 0;
}

static int lm_trans_root_has_explicit_l2_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Structure *root) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    if (root == 0) {
        return 0;
    }
    field = root -> first_field;
    while (field != 0) {
        node = field -> value;
        if (node != 0 && node -> kind == LM_P0_NODE_FRAME && (lm_trans_frame_is_l2_level_receiver(lm_lmx_message_thread, node -> as -> frame) || lm_trans_frame_is_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame))) {
            return 1;
        }
        field = field -> next;
    }
    return 0;
}

static int lm_trans_materialize_local_l2_source_structure(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Structure *body, const char *source_path) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmTransHeadBinding * binding;
    int ready;
    int source_only;
    int status;
    if (namespace_ == 0 || source_path == 0) {
        return 1;
    }
    binding = lm_trans_head_binding_new(lm_lmx_message_thread);
    if (binding == 0) {
        return 1;
    }
    status = 0;
    field = 0;
    if (body != 0) {
        field = body -> first_field;
    }
    while (status == 0 && field != 0) {
        node = field -> value;
        if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0 && node -> kind == LM_P0_NODE_FRAME && lm_trans_registry_early_l2_source_site_is_materialized(lm_lmx_message_thread, source_path, node) == 0) {
            if (lm_trans_head_binding_resolve(lm_lmx_message_thread, namespace_, node -> as -> frame -> head, binding) != 0) {
                status = 1;
            }
            else {
                if (binding -> statement_frame == &lm_trans_statement_emit_table) {
                    source_only = 0;
                    status = lm_trans_l2_table_body_is_source_only(lm_lmx_message_thread, node -> as -> frame -> body, "table", &source_only);
                    if (status == 0 && source_only != 0) {
                        status = lm_trans_materialize_l2_table_source(lm_lmx_message_thread, namespace_, node -> as -> frame, 0);
                        if (status == 0) {
                            status = lm_trans_registry_note_early_l2_source_site(lm_lmx_message_thread, source_path, node);
                        }
                    }
                }
                else {
                    if (binding -> statement_frame == &lm_trans_statement_emit_join) {
                        source_only = 0;
                        status = lm_trans_l2_join_is_source_only(lm_lmx_message_thread, node -> as -> frame, &source_only);
                        if (status == 0 && source_only != 0) {
                            ready = 0;
                            status = lm_trans_l2_join_sources_ready(lm_lmx_message_thread, namespace_, node -> as -> frame, &ready);
                            if (status == 0 && ready != 0) {
                                status = lm_trans_materialize_l2_join_source(lm_lmx_message_thread, namespace_, node -> as -> frame);
                                if (status == 0) {
                                    status = lm_trans_registry_note_early_l2_source_site(lm_lmx_message_thread, source_path, node);
                                }
                            }
                        }
                    }
                }
            }
        }
        field = field -> next;
    }
    lm_own_delete(binding, 0);
    return status;
}

static int lm_trans_materialize_local_l2_source_root(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *root, const char *source_path, int implicit_l2) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const char *previous_source_path;
    LmTransNamespace * namespace_;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE || source_path == 0) {
        return 1;
    }
    namespace_ = lm_trans_namespace_new(lm_lmx_message_thread);
    if (namespace_ == 0) {
        return 1;
    }
    if (lm_trans_namespace_attach_registry(lm_lmx_message_thread, namespace_) != 0) {
        lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = source_path;
    status = 0;
    if (implicit_l2 != 0 && lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        status = lm_trans_materialize_local_l2_source_structure(lm_lmx_message_thread, namespace_, root -> as -> structure, source_path);
    }
    else {
        field = root -> as -> structure -> first_field;
        while (status == 0 && field != 0) {
            node = field -> value;
            if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0 && node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                status = lm_trans_materialize_local_l2_source_structure(lm_lmx_message_thread, namespace_, node -> as -> frame -> body, source_path);
            }
            field = field -> next;
        }
    }
    lm_trans_current_source_path = previous_source_path;
    lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
    return status;
}

static int lm_trans_materialize_l2_predef_structure(struct LmMessageThread *lm_lmx_message_thread, LmTransNamespace *namespace_, const LmP0Structure *body) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmTransHeadBinding * binding;
    LmTransFunctionHeader * function;
    int function_status;
    int source_only;
    int status;
    if (namespace_ == 0) {
        return 1;
    }
    binding = lm_trans_head_binding_new(lm_lmx_message_thread);
    function = lm_trans_function_header_new(lm_lmx_message_thread);
    if (binding == 0 || function == 0) {
        lm_trans_function_header_destroy(lm_lmx_message_thread, function);
        lm_own_delete(binding, 0);
        return 1;
    }
    status = 0;
    field = 0;
    if (body != 0) {
        field = body -> first_field;
    }
    while (status == 0 && field != 0) {
        node = field -> value;
        if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0 && node -> kind == LM_P0_NODE_FRAME) {
            if (lm_trans_head_binding_resolve(lm_lmx_message_thread, namespace_, node -> as -> frame -> head, binding) != 0) {
                status = 1;
            }
            else {
                if (binding -> statement_frame == &lm_trans_statement_emit_table) {
                    source_only = 0;
                    status = lm_trans_l2_table_body_is_source_only(lm_lmx_message_thread, node -> as -> frame -> body, "table", &source_only);
                    if (status == 0 && source_only != 0) {
                        status = lm_trans_materialize_l2_table_source(lm_lmx_message_thread, namespace_, node -> as -> frame, 0);
                        if (status == 0) {
                            status = lm_trans_registry_note_early_l2_source_site(lm_lmx_message_thread, lm_trans_current_source_path, node);
                        }
                    }
                }
                else {
                    if (binding -> statement_frame == &lm_trans_statement_emit_join) {
                        source_only = 0;
                        status = lm_trans_l2_join_is_source_only(lm_lmx_message_thread, node -> as -> frame, &source_only);
                        if (status == 0 && source_only != 0) {
                            status = lm_trans_materialize_l2_join_source(lm_lmx_message_thread, namespace_, node -> as -> frame);
                            if (status == 0) {
                                status = lm_trans_registry_note_early_l2_source_site(lm_lmx_message_thread, lm_trans_current_source_path, node);
                            }
                        }
                    }
                }
                if (status == 0 && binding -> function_receiver_binding != 0 && (strcmp(binding -> function_receiver_binding, "lm_trans_receiver_fn") == 0 || strcmp(binding -> function_receiver_binding, "lm_trans_receiver_callable") == 0 || strcmp(binding -> function_receiver_binding, "lm_trans_receiver_sub") == 0)) {
                    lm_trans_function_header_destroy(lm_lmx_message_thread, function);
                    function = lm_trans_function_header_new(lm_lmx_message_thread);
                    if (function == 0) {
                        status = 1;
                    }
                    else {
                        function_status = (binding->function_receiver)(lm_lmx_message_thread, node -> as -> frame, 0, function);
                        if (function_status < 0) {
                            status = 1;
                        }
                        if (function_status > 0 && function -> is_descriptor_only) {
                            if (function -> is_sub) {
                                status = lm_trans_registry_materialize_sub_descriptor_frame(lm_lmx_message_thread, node -> as -> frame);
                            }
                            else {
                                status = lm_trans_registry_materialize_fn_descriptor_frame(lm_lmx_message_thread, node -> as -> frame);
                            }
                            if (status == 0) {
                                status = lm_trans_registry_note_predefined_descriptor_site(lm_lmx_message_thread, lm_trans_current_source_path, node);
                            }
                        }
                    }
                }
            }
        }
        field = field -> next;
    }
    lm_trans_function_header_destroy(lm_lmx_message_thread, function);
    lm_own_delete(binding, 0);
    return status;
}

static int lm_trans_materialize_l2_bootstrap_root(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *root, const char *source_path) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const char *previous_source_path;
    LmTransNamespace * namespace_;
    int materialized;
    int source_only;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE || source_path == 0) {
        return 1;
    }
    namespace_ = lm_trans_namespace_new(lm_lmx_message_thread);
    if (namespace_ == 0) {
        return 1;
    }
    if (lm_trans_namespace_attach_registry(lm_lmx_message_thread, namespace_) != 0) {
        lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = source_path;
    materialized = 0;
    status = 0;
    field = root -> as -> structure -> first_field;
    while (status == 0 && field != 0) {
        node = field -> value;
        if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind != LM_P0_NODE_FRAME) {
                fprintf(stderr, "trans L2 bootstrap error: root expects only table or join receiver frames\n");
                status = 1;
            }
            else {
                source_only = 0;
                if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "table")) {
                    status = lm_trans_l2_table_body_is_source_only(lm_lmx_message_thread, node -> as -> frame -> body, "table", &source_only);
                }
                else {
                    if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "join")) {
                        status = lm_trans_l2_join_is_source_only(lm_lmx_message_thread, node -> as -> frame, &source_only);
                    }
                    else {
                        fprintf(stderr, "trans L2 bootstrap error: root expects only table or join receiver frames\n");
                        status = 1;
                    }
                }
                if (status == 0 && source_only == 0) {
                    fprintf(stderr, "trans L2 bootstrap error: table and join receiver frames require an explicit first source marker\n");
                    status = 1;
                }
            }
        }
        field = field -> next;
    }
    field = root -> as -> structure -> first_field;
    while (status == 0 && field != 0) {
        node = field -> value;
        if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "table")) {
                status = lm_trans_materialize_l2_table_source(lm_lmx_message_thread, namespace_, node -> as -> frame, 0);
            }
            else {
                status = lm_trans_materialize_l2_join_source(lm_lmx_message_thread, namespace_, node -> as -> frame);
            }
            if (status == 0) {
                status = lm_trans_registry_note_early_l2_source_site(lm_lmx_message_thread, source_path, node);
                if (status == 0) {
                    materialized = 1;
                }
            }
        }
        field = field -> next;
    }
    if (status == 0 && materialized == 0) {
        fprintf(stderr, "trans L2 bootstrap error: no source table or source join receiver frames found\n");
        status = 1;
    }
    lm_trans_current_source_path = previous_source_path;
    lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
    return status;
}

static int lm_trans_materialize_l2_predef_root(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *root, const char *source_path) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    const char *previous_source_path;
    LmTransNamespace * namespace_;
    int previous_depth;
    int status;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    namespace_ = lm_trans_namespace_new(lm_lmx_message_thread);
    if (namespace_ == 0) {
        return 1;
    }
    if (lm_trans_namespace_attach_registry(lm_lmx_message_thread, namespace_) != 0) {
        lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
        return 1;
    }
    previous_source_path = lm_trans_current_source_path;
    lm_trans_current_source_path = source_path;
    status = 0;
    if (lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        status = lm_trans_materialize_l2_predef_structure(lm_lmx_message_thread, namespace_, root -> as -> structure);
    }
    else {
        field = root -> as -> structure -> first_field;
        while (status == 0 && field != 0) {
            node = field -> value;
            if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0 && node -> kind == LM_P0_NODE_FRAME && lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
                status = lm_trans_materialize_l2_predef_structure(lm_lmx_message_thread, namespace_, node -> as -> frame -> body);
                lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
            }
            field = field -> next;
        }
    }
    lm_trans_current_source_path = previous_source_path;
    lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
    return status;
}

static int lm_trans_typedef_projection_reserve_loaded_source_paths(struct LmMessageThread *lm_lmx_message_thread) {
    (void)lm_lmx_message_thread;
    const char *source_path;
    LmP0Document * document;
    size_t index;
    int status;
    if (lm_trans_registry == 0 || lm_trans_registry -> loaded_paths == 0) {
        return 0;
    }
    index = 0U;
    status = 0;
    while (status == 0 && index < lm_trans_registry -> loaded_paths -> count) {
        source_path = ((const char *)lm_own_ptr_stack_at(lm_trans_registry -> loaded_paths, index));
        document = 0;
        if (source_path == 0 || lm_trans_import_parse_document(lm_lmx_message_thread, source_path, &document, "identifier reservation") != 0) {
            status = 1;
        }
        else {
            status = lm_trans_typedef_projection_reserve_source_node(lm_lmx_message_thread, lm_p0_document_root(lm_lmx_message_thread, document));
        }
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        index = index + 1U;
    }
    return status;
}

static int lm_trans_emit_root_sequence(struct LmMessageThread *lm_lmx_message_thread, FILE *output, const LmP0Node *root, int implicit_l2, int *emitted) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    FILE * prelude_file;
    int handled;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    if (lm_trans_typedef_projection_reserve_loaded_source_paths(lm_lmx_message_thread) != 0 || lm_trans_typedef_projection_reserve_source_node(lm_lmx_message_thread, root) != 0 || lm_trans_module_init_names_prepare(lm_lmx_message_thread) != 0) {
        return 1;
    }
    prelude_file = lm_trans_prelude_file(lm_lmx_message_thread, output);
    if (implicit_l2 && lm_trans_root_has_explicit_l2_frame(lm_lmx_message_thread, root -> as -> structure) == 0) {
        if (lm_trans_emit_l2_structure(lm_lmx_message_thread, output, root -> as -> structure, 0) != 0) {
            return 1;
        }
        if (emitted != 0) {
            emitted[0] = 1;
        }
        return 0;
    }
    field = root -> as -> structure -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node -> kind == LM_P0_NODE_ATOM) {
                fprintf(stderr, "trans error: root raw text must be inside L1\n");
                return 1;
            }
            if (node -> kind != LM_P0_NODE_FRAME) {
                fprintf(stderr, "trans error: root field must be L1, L2, L3, os, ifdef, include, raw L1 text, or end: L1\n");
                return 1;
            }
            handled = 0;
            if (lm_trans_frame_is_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                if (lm_trans_emit_l1_body(lm_lmx_message_thread, prelude_file, node -> as -> frame, emitted) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_frame_is_l2_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                if (lm_trans_emit_l2_frame(lm_lmx_message_thread, output, node -> as -> frame) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_frame_is_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                if (lm_trans_emit_l3_frame(lm_lmx_message_thread, output, node -> as -> frame) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "os")) {
                if (lm_trans_emit_l1_os_frame(lm_lmx_message_thread, prelude_file, node -> as -> frame) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "ifdef")) {
                if (lm_trans_emit_l1_ifdef_frame(lm_lmx_message_thread, prelude_file, node -> as -> frame) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "include")) {
                if (lm_trans_emit_l1_include_frame(lm_lmx_message_thread, prelude_file, node -> as -> frame) != 0) {
                    return 1;
                }
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0 && lm_trans_end_frame_targets_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                if (emitted != 0) {
                    emitted[0] = 1;
                }
                handled = 1;
            }
            if (handled == 0) {
                fprintf(stderr, "trans error: root field must be L1, L2, L3, os, ifdef, include, raw L1 text, or end: L1\n");
                return 1;
            }
        }
        field = field -> next;
    }
    return 0;
}

static int lm_trans_string_stack_has(struct LmMessageThread *lm_lmx_message_thread, const LmOwnPtrStack *stack, const char *value) {
    (void)lm_lmx_message_thread;
    size_t i;
    const char *item;
    if (stack == 0 || value == 0) {
        return 0;
    }
    i = 0U;
    while (i < stack -> count) {
        item = lm_own_ptr_stack_at(stack, i);
        if (item != 0 && strcmp(item, value) == 0) {
            return 1;
        }
        i = i + 1U;
    }
    return 0;
}

