static int lm_trans_layout_class_requires_pointer_field(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *class_name) {
    (void)lm_lmx_message_thread;
    LmP0Text * class_text;
    int result;
    if (class_name == 0) {
        return 0;
    }
    class_text = lm_trans_l4_text_view_new(lm_lmx_message_thread, class_name);
    if (class_text == 0) {
        return 0;
    }
    result = lm_trans_layout_type_implicit_address_depth(lm_lmx_message_thread, class_text, namespace_) != 0U;
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &class_text);
    return result;
}

static size_t lm_trans_layout_field_effective_address_depth(struct LmMessageThread *lm_lmx_message_thread, const LmTransLayoutField *field, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t depth;
    if (field == 0) {
        return 0U;
    }
    depth = field -> address_depth;
    if (field -> is_union) {
        return depth;
    }
    if (lm_trans_layout_class_requires_pointer_field(lm_lmx_message_thread, namespace_, field -> class_name)) {
        return depth + 1U;
    }
    return depth;
}

static LmTransAbiParam * * lm_trans_l4_abi_params_new(struct LmMessageThread *lm_lmx_message_thread, size_t capacity) {
    (void)lm_lmx_message_thread;
    LmTransAbiParam * *params;
    size_t i;
    if (capacity == 0U) {
        return 0;
    }
    params = lm_own_new_zero(sizeof(params[0]) * capacity);
    if (params == 0) {
        return 0;
    }
    i = 0U;
    while (i < capacity) {
        params[i] = lm_own_new_zero(sizeof(params[i][0]));
        if (params[i] == 0) {
            while (i != 0U) {
                i = i - 1U;
                lm_own_delete(params[i], 0);
            }
            lm_own_delete(params, 0);
            return 0;
        }
        i = i + 1U;
    }
    return params;
}

