static const char * lm_trans_registry_layout_view_backend(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const LmRegistryViewRow *view_row) {
    (void)lm_lmx_message_thread;
    LmTransRegistryFact * facade_row;
    const char *backend;
    if (view_row == 0 || view_row -> payload == 0) {
        return 0;
    }
    backend = view_row -> payload;
    facade_row = ((LmTransRegistryFact *)view_row -> source);
    if (facade_row != 0 && facade_row -> payload != 0) {
        backend = lm_trans_registry_source_path_n2_named_typed_value(lm_lmx_message_thread, namespace_, "layout.backend", "class", "class", "backend", "class", facade_row);
    }
    return backend;
}

static int lm_trans_registry_collect_layout_names(struct LmMessageThread *lm_lmx_message_thread, LmOwnPtrStack *names, const LmTransNamespace *namespace_) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t row_count;
    LmTransRegistryFact * row;
    const LmOwnPtrStack * rows;
    const LmRegistryView * view;
    const LmRegistryViewRow * view_row;
    const char *backend;
    char *name;
    LmP0Text * key_text;
    if (names == 0) {
        return 1;
    }
    key_text = lm_trans_l4_text_view_new(lm_lmx_message_thread, "");
    if (key_text == 0) {
        return 1;
    }
    view = lm_trans_namespace_registry_view(lm_lmx_message_thread, namespace_);
    if (view != 0) {
        row_count = lm_registry_view_table_row_count(lm_lmx_message_thread, view, "layout.backend");
        i = 0U;
        while (i < row_count) {
            view_row = lm_registry_view_table_row_at(lm_lmx_message_thread, view, "layout.backend", i);
            backend = lm_trans_registry_layout_view_backend(lm_lmx_message_thread, namespace_, view_row);
            if (view_row != 0 && view_row -> key != 0 && backend != 0 && lm_trans_layout_backend_is_supported(lm_lmx_message_thread, backend)) {
                if (lm_trans_registry_append_relation_name(lm_lmx_message_thread, names, namespace_, "layout", "backend", "layout", 1, key_text, view_row -> key) != 0) {
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
                    return 1;
                }
            }
            i = i + 1U;
        }
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
        return 0;
    }
    rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, lm_trans_text_from_cstr(lm_lmx_message_thread, "layout"), "backend");
    if (rows == 0) {
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
        return 0;
    }
    i = 0U;
    while (i < rows -> count) {
        row = lm_own_ptr_stack_at(rows, i);
        if (row != 0 && row -> key != 0 && row -> payload != 0 && lm_trans_layout_backend_is_supported(lm_lmx_message_thread, row -> payload)) {
            lm_trans_text_assign_cstr(lm_lmx_message_thread, key_text, row -> key);
            if (lm_trans_namespace_class_has(lm_lmx_message_thread, namespace_, key_text) == 0) {
                fprintf(stderr, "trans L4 layout error: layout.backend key %s is not a class\n", row -> key);
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
                return 1;
            }
            name = lm_trans_text_copy_cstr(lm_lmx_message_thread, key_text);
            if (name == 0) {
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
                return 1;
            }
            if (lm_trans_string_stack_has(lm_lmx_message_thread, names, name)) {
                lm_own_delete(name, 0);
            }
            else {
                if (lm_own_ptr_stack_push(names, name) != 0) {
                    lm_own_delete(name, 0);
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
                    return 1;
                }
            }
        }
        i = i + 1U;
    }
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &key_text);
    return 0;
}

static const char * lm_trans_layout_field_source_value(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *layout_name, const char *relation_name, const char *n2_value_column_name, const char *value_descriptor, const LmTransRegistryFact *facade_row, const LmTableCell **out_key_cell) {
    (void)lm_lmx_message_thread;
    const LmTableCell * source_key_cell;
    const LmTableCell * source_value_cell;
    char *source_path;
    size_t source_path_length;
    const char *value;
    if (out_key_cell != 0) {
        out_key_cell[0] = 0;
    }
    if (layout_name == 0 || relation_name == 0 || n2_value_column_name == 0 || value_descriptor == 0 || facade_row == 0 || facade_row -> payload == 0) {
        return 0;
    }
    value = facade_row -> payload;
    source_path = lm_trans_registry_source_relation_path_new(lm_lmx_message_thread, layout_name, relation_name, &source_path_length);
    if (source_path == 0) {
        return value;
    }
    source_key_cell = 0;
    source_value_cell = lm_trans_registry_source_path_typed_cell_kind(lm_lmx_message_thread, namespace_, source_path, "class", "class", value_descriptor, n2_value_column_name, facade_row, 0, &source_key_cell);
    if (source_value_cell != 0 && lm_trans_registry_view_is_selected(lm_lmx_message_thread) != 0) {
        value = source_value_cell -> value;
        if (out_key_cell != 0) {
            out_key_cell[0] = source_key_cell;
        }
    }
    lm_own_delete(source_path, 0);
    return value;
}

static int lm_trans_collect_layout_field_common(struct LmMessageThread *lm_lmx_message_thread, const char *layout_name, const LmTransNamespace *namespace_, const char *field_name, const LmOwnPtrStack *index_rows, const LmOwnPtrStack *address_depth_rows, const LmOwnPtrStack *const_rows, const LmOwnPtrStack *array_count_rows, LmTransLayoutField *field) {
    (void)lm_lmx_message_thread;
    size_t index;
    LmTransRegistryFact * index_row;
    LmTransRegistryFact * address_depth_row;
    LmTransRegistryFact * const_row;
    LmTransRegistryFact * array_count_row;
    const char *index_payload;
    const char *address_depth_payload;
    const char *const_payload;
    const char *array_count_payload;
    LmP0Text * field_text;
    if (layout_name == 0 || field_name == 0 || field == 0) {
        return 1;
    }
    field_text = lm_trans_l4_text_view_new(lm_lmx_message_thread, field_name);
    if (field_text == 0) {
        return 1;
    }
    index_row = lm_trans_registry_relation_stack_latest_row(lm_lmx_message_thread, index_rows, field_text);
    address_depth_row = lm_trans_registry_relation_stack_latest_row(lm_lmx_message_thread, address_depth_rows, field_text);
    const_row = lm_trans_registry_relation_stack_latest_row(lm_lmx_message_thread, const_rows, field_text);
    array_count_row = lm_trans_registry_relation_stack_latest_row(lm_lmx_message_thread, array_count_rows, field_text);
    index_payload = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.index", "index", "size_t", index_row, 0);
    address_depth_payload = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.address-depth", "depth", "size_t", address_depth_row, 0);
    const_payload = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.const", "value", "int", const_row, 0);
    array_count_payload = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.array-count", "count", "size_t", array_count_row, 0);
    if (index_payload == 0 || lm_trans_parse_size_payload(lm_lmx_message_thread, index_payload, &index) == 0) {
        fprintf(stderr, "trans L4 layout error: field %s.%s requires field.index\n", layout_name, field_name);
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &field_text);
        return 1;
    }
    memset(field, 0, sizeof(field[0]));
    field->name = field_name;
    field->index = index;
    if (address_depth_payload != 0 && lm_trans_parse_size_payload(lm_lmx_message_thread, address_depth_payload, &field -> address_depth) == 0) {
        fprintf(stderr, "trans L4 layout error: field %s.%s has invalid field.address-depth\n", layout_name, field_name);
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &field_text);
        return 1;
    }
    if (const_payload != 0) {
        if (lm_trans_parse_size_payload(lm_lmx_message_thread, const_payload, &index) == 0) {
            fprintf(stderr, "trans L4 layout error: field %s.%s has invalid field.const\n", layout_name, field_name);
            lm_trans_l4_text_view_delete(lm_lmx_message_thread, &field_text);
            return 1;
        }
        field->is_const = index != 0U;
    }
    if (array_count_payload != 0) {
        if (lm_trans_parse_size_payload(lm_lmx_message_thread, array_count_payload, &field -> array_count) == 0) {
            fprintf(stderr, "trans L4 layout error: field %s.%s has invalid field.array-count\n", layout_name, field_name);
            lm_trans_l4_text_view_delete(lm_lmx_message_thread, &field_text);
            return 1;
        }
        field->has_array_count = 1;
    }
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &field_text);
    return 0;
}

static int lm_trans_collect_descriptor_layout_fields(struct LmMessageThread *lm_lmx_message_thread, const char *layout_name, const LmTransDescriptor *descriptor, const LmTransNamespace *namespace_, LmTransLayoutField **fields, size_t capacity, size_t *out_count) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t field_count;
    const LmTransDescriptorField * descriptor_field;
    LmTransLayoutField * field;
    if (out_count != 0) {
        out_count[0] = 0U;
    }
    if (layout_name == 0 || descriptor == 0 || descriptor -> has_structural_fields == 0 || descriptor -> structural_fields == 0 || fields == 0 || out_count == 0) {
        return 1;
    }
    field_count = descriptor -> structural_fields -> count;
    if (field_count > capacity) {
        fprintf(stderr, "trans L4 layout error: too many fields in %s\n", layout_name);
        return 1;
    }
    i = 0U;
    while (i < field_count) {
        descriptor_field = lm_own_ptr_stack_at(descriptor -> structural_fields, i);
        if (descriptor_field == 0 || descriptor_field -> name == 0 || descriptor_field -> descriptor_name == 0) {
            fprintf(stderr, "trans L4 layout error: descriptor for %s has an invalid structural field\n", layout_name);
            return 1;
        }
        field = fields[i];
        memset(field, 0, sizeof(field[0]));
        field->name = descriptor_field -> name;
        field->index = descriptor_field -> index;
        field->address_depth = descriptor_field -> address_depth;
        field->array_count = descriptor_field -> array_count;
        field->is_const = descriptor_field -> is_const;
        field->has_array_count = descriptor_field -> has_array_count;
        field->is_union = descriptor_field -> is_union;
        if (descriptor_field -> is_union) {
            field->union_layout_name = descriptor_field -> descriptor_name;
        }
        else {
            field->class_name = descriptor_field -> descriptor_name;
            if (field -> is_const && lm_trans_layout_field_effective_address_depth(lm_lmx_message_thread, field, namespace_) == 0U && field -> has_array_count == 0) {
                fprintf(stderr, "trans L4 layout error: field %s.%s const value fields are not supported yet\n", layout_name, field -> name);
                return 1;
            }
        }
        i = i + 1U;
    }
    out_count[0] = field_count;
    return 0;
}

static int lm_trans_collect_layout_fields(struct LmMessageThread *lm_lmx_message_thread, const char *layout_name, const LmTransNamespace *namespace_, LmTransLayoutField **fields, size_t capacity, size_t *out_count) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t field_count;
    LmTransRegistryFact * row;
    LmTransLayoutField * field;
    const LmOwnPtrStack * class_rows;
    const LmOwnPtrStack * union_rows;
    const LmOwnPtrStack * index_rows;
    const LmOwnPtrStack * address_depth_rows;
    const LmOwnPtrStack * const_rows;
    const LmOwnPtrStack * array_count_rows;
    const LmTableCell * source_key_cell;
    const char *field_class_name;
    const char *union_layout_name;
    const LmTransDescriptor * descriptor;
    int descriptor_status;
    LmP0Text * layout_text;
    if (layout_name == 0 || fields == 0 || out_count == 0) {
        return 1;
    }
    layout_text = lm_trans_l4_text_view_new(lm_lmx_message_thread, layout_name);
    if (layout_text == 0) {
        return 1;
    }
    descriptor = lm_trans_namespace_descriptor(lm_lmx_message_thread, namespace_, layout_text);
    if (descriptor != 0 && descriptor -> has_structural_fields) {
        descriptor_status = lm_trans_collect_descriptor_layout_fields(lm_lmx_message_thread, layout_name, descriptor, namespace_, fields, capacity, out_count);
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
        return descriptor_status;
    }
    class_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.class");
    union_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.union");
    index_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.index");
    address_depth_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.address-depth");
    const_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.const");
    array_count_rows = lm_trans_namespace_registry_relation_stack(lm_lmx_message_thread, namespace_, layout_text, "field.array-count");
    if (class_rows == 0 && union_rows == 0) {
        fprintf(stderr, "trans L4 layout error: layout %s requires field.class or field.union facts\n", layout_name);
        lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
        return 1;
    }
    field_count = 0U;
    if (class_rows != 0) {
        i = 0U;
        while (i < class_rows -> count) {
            row = lm_own_ptr_stack_at(class_rows, i);
            if (row != 0 && row -> key != 0 && row -> payload != 0) {
                if (field_count >= capacity) {
                    fprintf(stderr, "trans L4 layout error: too many fields in %s\n", layout_name);
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
                    return 1;
                }
                field = fields[field_count];
                if (lm_trans_collect_layout_field_common(lm_lmx_message_thread, layout_name, namespace_, row -> key, index_rows, address_depth_rows, const_rows, array_count_rows, field) != 0) {
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
                    return 1;
                }
                source_key_cell = 0;
                field_class_name = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.class", "field", "class", row, &source_key_cell);
                field->class_name = field_class_name;
                if (source_key_cell != 0 && source_key_cell -> value != 0) {
                    field->name = source_key_cell -> value;
                }
                if (field -> is_const && lm_trans_layout_field_effective_address_depth(lm_lmx_message_thread, field, namespace_) == 0U && field -> has_array_count == 0) {
                    fprintf(stderr, "trans L4 layout error: field %s.%s const value fields are not supported yet\n", layout_name, row -> key);
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
                    return 1;
                }
                field_count = field_count + 1U;
            }
            i = i + 1U;
        }
    }
    if (union_rows != 0) {
        i = 0U;
        while (i < union_rows -> count) {
            row = lm_own_ptr_stack_at(union_rows, i);
            if (row != 0 && row -> key != 0 && row -> payload != 0) {
                if (field_count >= capacity) {
                    fprintf(stderr, "trans L4 layout error: too many fields in %s\n", layout_name);
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
                    return 1;
                }
                field = fields[field_count];
                if (lm_trans_collect_layout_field_common(lm_lmx_message_thread, layout_name, namespace_, row -> key, index_rows, address_depth_rows, const_rows, array_count_rows, field) != 0) {
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
                    return 1;
                }
                field->is_union = 1;
                source_key_cell = 0;
                union_layout_name = lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, "field.union", "union", "class", row, &source_key_cell);
                field->union_layout_name = union_layout_name;
                if (source_key_cell != 0 && source_key_cell -> value != 0) {
                    field->name = source_key_cell -> value;
                }
                field_count = field_count + 1U;
            }
            i = i + 1U;
        }
    }
    out_count[0] = field_count;
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &layout_text);
    return 0;
}

static int lm_trans_sort_layout_fields(struct LmMessageThread *lm_lmx_message_thread, LmTransLayoutField **fields, size_t field_count) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t j;
    LmTransLayoutField * swap;
    if (fields == 0) {
        return 1;
    }
    i = 0U;
    while (i < field_count) {
        j = i + 1U;
        while (j < field_count) {
            if (fields[j] -> index < fields[i] -> index) {
                swap = fields[i];
                fields[i] = fields[j];
                fields[j] = swap;
            }
            j = j + 1U;
        }
        i = i + 1U;
    }
    return 0;
}

static const char * lm_trans_registry_layout_row_field_name(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *layout_name, const char *relation_name, const char *value_column_name, const LmTransRegistryFact *row) {
    (void)lm_lmx_message_thread;
    const LmTableCell * source_key_cell;
    if (layout_name == 0 || relation_name == 0 || value_column_name == 0 || row == 0 || row -> key == 0 || row -> payload == 0) {
        return 0;
    }
    source_key_cell = 0;
    lm_trans_layout_field_source_value(lm_lmx_message_thread, namespace_, layout_name, relation_name, value_column_name, "class", row, &source_key_cell);
    if (source_key_cell != 0 && source_key_cell -> value != 0) {
        return source_key_cell -> value;
    }
    return row -> key;
}

static const char * lm_trans_registry_relation_rows_duplicate_field_name(struct LmMessageThread *lm_lmx_message_thread, const LmTransNamespace *namespace_, const char *layout_name, const LmOwnPtrStack *left_rows, const char *left_relation_name, const char *left_value_column_name, const LmOwnPtrStack *right_rows, const char *right_relation_name, const char *right_value_column_name, int same_rows) {
    (void)lm_lmx_message_thread;
    size_t i;
    size_t j;
    const LmTransRegistryFact * left;
    const LmTransRegistryFact * right;
    const char *left_name;
    const char *right_name;
    if (left_rows == 0 || right_rows == 0) {
        return 0;
    }
    i = 0U;
    while (i < left_rows -> count) {
        left = lm_own_ptr_stack_at(left_rows, i);
        left_name = lm_trans_registry_layout_row_field_name(lm_lmx_message_thread, namespace_, layout_name, left_relation_name, left_value_column_name, left);
        if (left_name != 0) {
            j = 0U;
            if (same_rows) {
                j = i + 1U;
            }
            while (j < right_rows -> count) {
                right = lm_own_ptr_stack_at(right_rows, j);
                right_name = lm_trans_registry_layout_row_field_name(lm_lmx_message_thread, namespace_, layout_name, right_relation_name, right_value_column_name, right);
                if (right_name != 0 && strcmp(left_name, right_name) == 0) {
                    return left_name;
                }
                j = j + 1U;
            }
        }
        i = i + 1U;
    }
    return 0;
}

