static int lm_trans_l4_callable_type_from_node(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *node, LmTransL4CallableType *out) {
    (void)lm_lmx_message_thread;
    const LmP0Node * current;
    const LmP0Frame * frame;
    const LmP0Field * field;
    LmP0Text * dimension;
    size_t dimension_index;
    size_t rank;
    if (node == 0 || out == 0) {
        return 0;
    }
    if (lm_trans_callable_type_reset(lm_lmx_message_thread, out) != 0) {
        return 0;
    }
    current = node;
    while (current != 0) {
        if (current -> kind == LM_P0_NODE_STRUCTURE) {
            field = current -> as -> structure -> first_field;
            if (field == 0 || field -> next != 0 || field -> value == 0) {
                return 0;
            }
            current = field -> value;
            continue;
        }
        if (current -> kind == LM_P0_NODE_ATOM) {
            if (lm_trans_registry_identifier_value(lm_lmx_message_thread, current -> as -> atom, out -> class_name) == 0) {
                return 0;
            }
            return 1;
        }
        if (current -> kind != LM_P0_NODE_FRAME) {
            return 0;
        }
        frame = current -> as -> frame;
        if (lm_trans_text_equals(lm_lmx_message_thread, frame -> head, "const")) {
            field = frame -> body -> first_field;
            if (field == 0 || field -> next != 0 || field -> value == 0) {
                return 0;
            }
            out->is_const = 1;
            current = field -> value;
            continue;
        }
        if (lm_trans_text_all_char(lm_lmx_message_thread, frame -> head, '@')) {
            field = frame -> body -> first_field;
            if (field == 0 || field -> value == 0) {
                return 0;
            }
            out->address_depth = out -> address_depth + frame -> head -> length;
            current = field -> value;
            continue;
        }
        if (lm_trans_text_is_array_receiver_head(lm_lmx_message_thread, frame -> head)) {
            field = frame -> body -> first_field;
            if (field == 0 || field -> value == 0) {
                return 0;
            }
            dimension = lm_trans_text_ref_new_cstr("");
            if (dimension == 0) {
                return 0;
            }
            dimension_index = 0U;
            rank = 0U;
            while (lm_trans_array_head_next_dimension(lm_lmx_message_thread, frame -> head, &dimension_index, dimension)) {
                rank = rank + 1U;
            }
            lm_trans_text_ref_destroy(&dimension);
            if (rank == 0U) {
                return 0;
            }
            out->array_rank = out -> array_rank + rank;
            out->address_depth = out -> address_depth + 1U;
            while (field != 0 && field -> value != 0 && field -> value -> kind == LM_P0_NODE_ATOM && field -> value -> as -> atom -> length != 0U && lm_trans_text_all_char(lm_lmx_message_thread, field -> value -> as -> atom, '@')) {
                if (field -> value -> as -> atom -> length > SIZE_MAX - out -> address_depth) {
                    return 0;
                }
                out->address_depth = out -> address_depth + field -> value -> as -> atom -> length;
                field = field -> next;
            }
            if (field == 0 || field -> value == 0) {
                return 0;
            }
            current = field -> value;
            continue;
        }
        if (lm_trans_registry_identifier_value(lm_lmx_message_thread, frame -> head, out -> class_name) == 0) {
            return 0;
        }
        return 1;
    }
    return 0;
}

