static int lm_trans_registry_load_import_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, const char *source_path) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmP0Text * path_value;
    char *candidate_name;
    char registry_path[4096];
    int loaded;
    if (frame == 0) {
        return 1;
    }
    field = frame -> body -> first_field;
    if (field == 0) {
        fprintf(stderr, "trans registry import error: import receiver expects at least one path\n");
        return 1;
    }
    path_value = lm_trans_l4_text_view_new(lm_lmx_message_thread, "");
    if (path_value == 0) {
        return 1;
    }
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node == 0 || node -> kind != LM_P0_NODE_ATOM || lm_trans_registry_literal_value(lm_lmx_message_thread, node -> as -> atom, path_value) == 0) {
                fprintf(stderr, "trans registry import error: import path must be an atom/string\n");
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            candidate_name = lm_trans_text_copy_cstr(lm_lmx_message_thread, path_value);
            if (candidate_name == 0) {
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
                lm_own_delete(candidate_name, 0);
                fprintf(stderr, "trans registry import error: import path is too long\n");
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            lm_own_delete(candidate_name, 0);
            if (lm_trans_path_has_extension(lm_lmx_message_thread, registry_path, ".lm4")) {
                fprintf(stderr, "trans L2 import error: import does not accept legacy .lm4 registry targets; migrate the module to .lm2 and load it with predef: %s\n", registry_path);
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            if (lm_trans_registry_path_already_loaded(lm_lmx_message_thread, registry_path) == 0) {
                if (lm_trans_registry_load_file_path(lm_lmx_message_thread, registry_path, 1, &loaded) != 0) {
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                    return 1;
                }
                if (loaded == 0) {
                    fprintf(stderr, "trans registry import error: cannot read %s\n", registry_path);
                    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                    return 1;
                }
            }
        }
        field = field -> next;
    }
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
    return 0;
}

static int lm_trans_registry_materialize_predef_path(struct LmMessageThread *lm_lmx_message_thread, const char *registry_path) {
    (void)lm_lmx_message_thread;
    LmP0Document * document;
    const LmP0Diagnostic * diagnostic;
    int loaded;
    int status;
    if (registry_path == 0) {
        fprintf(stderr, "trans registry predef error: predef target path is empty\n");
        return 1;
    }
    if (lm_trans_path_has_extension(lm_lmx_message_thread, registry_path, ".lm2") == 0) {
        fprintf(stderr, "trans registry predef error: predef target must be an .lm2 module: %s\n", registry_path);
        return 1;
    }
    if (lm_trans_registry_path_is_predefined(lm_lmx_message_thread, registry_path) != 0) {
        return 0;
    }
    if (lm_trans_registry_note_predefined_path(lm_lmx_message_thread, registry_path) != 0) {
        return 1;
    }
    if (lm_trans_registry_load_file_path(lm_lmx_message_thread, registry_path, 1, &loaded) != 0 || loaded == 0) {
        return 1;
    }
    document = 0;
    status = lm_p0_parse_file(lm_lmx_message_thread, registry_path, &document);
    if (status != 0) {
        diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, document);
        if (diagnostic != 0) {
            fprintf(stderr, "trans registry predef parse error %d at %zu:%zu in %s: %s\n", diagnostic -> code, diagnostic -> line, diagnostic -> column, registry_path, diagnostic -> message);
        }
        else {
            fprintf(stderr, "trans registry predef error: cannot read %s\n", registry_path);
        }
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        return 1;
    }
    status = lm_trans_materialize_l2_predef_root(lm_lmx_message_thread, lm_p0_document_root(lm_lmx_message_thread, document), registry_path);
    lm_p0_document_destroy(lm_lmx_message_thread, document);
    return status;
}

static int lm_trans_registry_load_predef_frame(struct LmMessageThread *lm_lmx_message_thread, const LmP0Frame *frame, const char *source_path) {
    (void)lm_lmx_message_thread;
    const LmP0Field * field;
    const LmP0Node * node;
    LmP0Text * path_value;
    char *candidate_name;
    char registry_path[4096];
    int found;
    if (frame == 0) {
        return 1;
    }
    path_value = lm_trans_l4_text_view_new(lm_lmx_message_thread, "");
    if (path_value == 0) {
        return 1;
    }
    found = 0;
    field = frame -> body -> first_field;
    while (field != 0) {
        node = field -> value;
        if (lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0) {
            if (node == 0 || node -> kind != LM_P0_NODE_ATOM || lm_trans_registry_literal_value(lm_lmx_message_thread, node -> as -> atom, path_value) == 0) {
                fprintf(stderr, "trans registry predef error: predef path must be an atom/string\n");
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            candidate_name = lm_trans_text_copy_cstr(lm_lmx_message_thread, path_value);
            if (candidate_name == 0) {
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
                lm_own_delete(candidate_name, 0);
                fprintf(stderr, "trans registry predef error: predef path is too long\n");
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            lm_own_delete(candidate_name, 0);
            if (lm_trans_registry_materialize_predef_path(lm_lmx_message_thread, registry_path) != 0) {
                lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
                return 1;
            }
            found = 1;
        }
        field = field -> next;
    }
    lm_trans_l4_text_view_delete(lm_lmx_message_thread, &path_value);
    if (found == 0) {
        fprintf(stderr, "trans registry predef error: predef receiver expects at least one .lm2 path\n");
        return 1;
    }
    return lm_trans_validate_end_trailer(lm_lmx_message_thread, frame);
}

static LmTransRegistryImportFrame * lm_trans_registry_import_frame_new(struct LmMessageThread *lm_lmx_message_thread, const LmP0Field *field, int descend_l2) {
    (void)lm_lmx_message_thread;
    LmTransRegistryImportFrame * frame;
    frame = lm_own_new_zero(sizeof(frame[0]));
    if (frame != 0) {
        frame->field = field;
        frame->descend_l2 = descend_l2;
    }
    return frame;
}

static int lm_trans_registry_load_imports_from_structure(struct LmMessageThread *lm_lmx_message_thread, const LmP0Structure *structure, const char *source_path, int descend_l2) {
    (void)lm_lmx_message_thread;
    LmOwnPtrStack * stack;
    LmTransRegistryImportFrame * frame;
    const LmP0Node * node;
    LmTransHeadBinding * binding;
    void *popped;
    int child_descend_l2;
    int previous_depth;
    int status;
    binding = lm_own_new_zero(sizeof(binding[0]));
    if (binding == 0) {
        return 1;
    }
    if (structure == 0 || structure -> first_field == 0) {
        lm_own_delete(binding, 0);
        return 0;
    }
    stack = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    if (stack == 0) {
        lm_own_delete(binding, 0);
        return 1;
    }
    frame = lm_trans_registry_import_frame_new(lm_lmx_message_thread, structure -> first_field, descend_l2);
    if (frame == 0) {
        lm_trans_ptr_stack_delete(&stack);
        lm_own_delete(binding, 0);
        return 1;
    }
    if (lm_own_ptr_stack_push(stack, frame) != 0) {
        lm_own_delete(frame, 0);
        lm_trans_ptr_stack_delete(&stack);
        lm_own_delete(binding, 0);
        return 1;
    }
    status = 0;
    while (status == 0 && stack -> count != 0U) {
        frame = lm_own_ptr_stack_top(stack);
        if (frame == 0 || frame -> field == 0) {
            popped = lm_own_ptr_stack_pop(stack);
            lm_own_delete(popped, 0);
            continue;
        }
        node = frame -> field -> value;
        frame->field = frame -> field -> next;
        if (node != 0 && lm_trans_node_is_ignored(lm_lmx_message_thread, node) == 0 && node -> kind == LM_P0_NODE_FRAME) {
            if (lm_trans_head_binding_resolve(lm_lmx_message_thread, 0, node -> as -> frame -> head, binding) != 0) {
                status = 1;
                break;
            }
            if (binding -> statement_frame == &lm_trans_statement_emit_import) {
                if (frame -> descend_l2 != 2 && lm_trans_registry_load_import_frame(lm_lmx_message_thread, node -> as -> frame, source_path) != 0) {
                    status = 1;
                    break;
                }
            }
            else {
                if (binding -> statement_frame == &lm_trans_statement_emit_predef) {
                    if (frame -> descend_l2 != 2 && lm_trans_registry_load_predef_frame(lm_lmx_message_thread, node -> as -> frame, source_path) != 0) {
                        status = 1;
                        break;
                    }
                }
                else {
                    if (frame -> descend_l2 != 0 && node -> as -> frame -> body != 0 && node -> as -> frame -> body -> first_field != 0 && (lm_trans_frame_is_l1_substrate_receiver(lm_lmx_message_thread, node -> as -> frame) != 0 || lm_trans_frame_is_l2_or_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame) != 0 || frame -> descend_l2 == 2 || lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "os") || lm_trans_text_equals(lm_lmx_message_thread, node -> as -> frame -> head, "ifdef"))) {
                        if (lm_trans_frame_is_l3_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                            previous_depth = lm_trans_l3_profile_enter_frame(lm_lmx_message_thread, node -> as -> frame);
                            status = lm_trans_registry_load_imports_from_structure(lm_lmx_message_thread, node -> as -> frame -> body, source_path, 0);
                            lm_trans_l3_profile_restore(lm_lmx_message_thread, previous_depth);
                            if (status != 0) {
                                break;
                            }
                        }
                        else {
                            if (lm_trans_frame_is_l2_level_receiver(lm_lmx_message_thread, node -> as -> frame)) {
                                child_descend_l2 = 0;
                            }
                            else {
                                child_descend_l2 = 2;
                            }
                            frame = lm_trans_registry_import_frame_new(lm_lmx_message_thread, node -> as -> frame -> body -> first_field, child_descend_l2);
                            if (frame == 0) {
                                status = 1;
                                break;
                            }
                            if (lm_own_ptr_stack_push(stack, frame) != 0) {
                                lm_own_delete(frame, 0);
                                status = 1;
                                break;
                            }
                        }
                    }
                }
            }
        }
    }
    lm_trans_ptr_stack_delete(&stack);
    lm_own_delete(binding, 0);
    return status;
}

static int lm_trans_registry_load_inline_root(struct LmMessageThread *lm_lmx_message_thread, const LmP0Node *root, const char *source_path) {
    (void)lm_lmx_message_thread;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
        return 1;
    }
    return lm_trans_registry_load_imports_from_structure(lm_lmx_message_thread, root -> as -> structure, source_path, 1);
}

static int lm_trans_path_separator(struct LmMessageThread *lm_lmx_message_thread, char ch) {
    (void)lm_lmx_message_thread;
    return ch == '/' || ch == '\\';
}

static int lm_trans_path_is_absolute(struct LmMessageThread *lm_lmx_message_thread, const char *path) {
    (void)lm_lmx_message_thread;
    if (path == 0 || path[0] == '\0') {
        return 0;
    }
    if (lm_trans_path_separator(lm_lmx_message_thread, path[0]) != 0) {
        return 1;
    }
    return ((path[0] >= 'A' && path[0] <= 'Z') || (path[0] >= 'a' && path[0] <= 'z')) && path[1] == ':' && lm_trans_path_separator(lm_lmx_message_thread, path[2]) != 0;
}

static int lm_trans_path_segment_equals(struct LmMessageThread *lm_lmx_message_thread, const char *path, size_t offset, const char *segment) {
    (void)lm_lmx_message_thread;
    size_t i;
    if (path == 0 || segment == 0) {
        return 0;
    }
    i = 0U;
    while (segment[i] != '\0') {
        if (path[offset + i] != segment[i]) {
            return 0;
        }
        i = i + 1U;
    }
    return path[offset + i] == '\0' || lm_trans_path_separator(lm_lmx_message_thread, path[offset + i]) != 0;
}

static size_t lm_trans_project_root_length_from_source(struct LmMessageThread *lm_lmx_message_thread, const char *source_path) {
    (void)lm_lmx_message_thread;
    size_t length;
    size_t i;
    if (source_path == 0 || lm_trans_path_is_absolute(lm_lmx_message_thread, source_path) == 0) {
        return 0U;
    }
    length = strlen(source_path);
    i = 0U;
    while (i < length) {
        if ((i == 0U || lm_trans_path_separator(lm_lmx_message_thread, source_path[i - 1U]) != 0) && (lm_trans_path_segment_equals(lm_lmx_message_thread, source_path, i, "lm2") != 0 || lm_trans_path_segment_equals(lm_lmx_message_thread, source_path, i, "lm4") != 0 || lm_trans_path_segment_equals(lm_lmx_message_thread, source_path, i, "tests") != 0)) {
            return i;
        }
        i = i + 1U;
    }
    return 0U;
}

static int lm_trans_registry_project_path_for_source(struct LmMessageThread *lm_lmx_message_thread, const char *source_path, const char *file_name, char *buffer, size_t size) {
    (void)lm_lmx_message_thread;
    size_t root_length;
    size_t file_length;
    if (buffer == 0 || file_name == 0 || size == 0U) {
        return 1;
    }
    root_length = lm_trans_project_root_length_from_source(lm_lmx_message_thread, source_path);
    file_length = strlen(file_name);
    if (root_length == 0U) {
        if (file_length >= size) {
            return 1;
        }
        strcpy(buffer, file_name);
        return 0;
    }
    if (root_length + file_length >= size) {
        fprintf(stderr, "trans error: registry path is too long\n");
        return 1;
    }
    memcpy(buffer, source_path, root_length);
    strcpy(buffer + root_length, file_name);
    return 0;
}

static int lm_trans_registry_path_for_source(struct LmMessageThread *lm_lmx_message_thread, const char *source_path, const char *file_name, char *buffer, size_t size) {
    (void)lm_lmx_message_thread;
    size_t length;
    size_t i;
    size_t slash;
    if (buffer == 0 || file_name == 0 || size == 0U) {
        return 1;
    }
    if (source_path == 0 || source_path[0] == '\0') {
        if (strlen(file_name) >= size) {
            return 1;
        }
        strcpy(buffer, file_name);
        return 0;
    }
    length = strlen(source_path);
    slash = 0U;
    i = 0U;
    while (i < length) {
        if (lm_trans_path_separator(lm_lmx_message_thread, source_path[i]) != 0) {
            slash = i + 1U;
        }
        i = i + 1U;
    }
    if (slash == 0U) {
        if (strlen(file_name) >= size) {
            return 1;
        }
        strcpy(buffer, file_name);
        return 0;
    }
    if (slash + strlen(file_name) >= size) {
        fprintf(stderr, "trans error: registry path is too long\n");
        return 1;
    }
    memcpy(buffer, source_path, slash);
    strcpy(buffer + slash, file_name);
    return 0;
}

static int lm_trans_registry_load_file_path_mode(struct LmMessageThread *lm_lmx_message_thread, const char *registry_path, int required, int bootstrap_l2, int *out_loaded) {
    (void)lm_lmx_message_thread;
    LmP0Document * document;
    const LmP0Diagnostic * diagnostic;
    int status;
    if (out_loaded != 0) {
        out_loaded[0] = 0;
    }
    if (registry_path == 0 || registry_path[0] == '\0') {
        if (required != 0) {
            fprintf(stderr, "trans registry error: empty registry path\n");
            return 1;
        }
        return 0;
    }
    if (lm_trans_path_has_extension(lm_lmx_message_thread, registry_path, ".lm4") != 0) {
        fprintf(stderr, "trans registry error: .lm4 registry modules are not supported: %s\n", registry_path);
        return 1;
    }
    if (lm_trans_registry_path_already_loaded(lm_lmx_message_thread, registry_path) != 0) {
        if (out_loaded != 0) {
            out_loaded[0] = 1;
        }
        return 0;
    }
    document = 0;
    status = lm_p0_parse_file(lm_lmx_message_thread, registry_path, &document);
    if (status != 0) {
        diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, document);
        if (diagnostic != 0) {
            fprintf(stderr, "trans registry parse error %d at %zu:%zu in %s: %s\n", diagnostic -> code, diagnostic -> line, diagnostic -> column, registry_path, diagnostic -> message);
            lm_p0_document_destroy(lm_lmx_message_thread, document);
            return 1;
        }
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        if (required != 0) {
            fprintf(stderr, "trans registry error: cannot read %s\n", registry_path);
            return 1;
        }
        return 0;
    }
    if (bootstrap_l2 != 0 && lm_trans_path_has_extension(lm_lmx_message_thread, registry_path, ".lm2") != 0) {
        status = lm_trans_materialize_l2_bootstrap_root(lm_lmx_message_thread, lm_p0_document_root(lm_lmx_message_thread, document), registry_path);
    }
    else {
        status = lm_trans_registry_load_inline_root(lm_lmx_message_thread, lm_p0_document_root(lm_lmx_message_thread, document), registry_path);
    }
    if (status != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        return 1;
    }
    lm_p0_document_destroy(lm_lmx_message_thread, document);
    if (lm_trans_registry_note_loaded_path(lm_lmx_message_thread, registry_path) != 0) {
        return 1;
    }
    if (out_loaded != 0) {
        out_loaded[0] = 1;
    }
    return 0;
}

static int lm_trans_registry_load_file_path(struct LmMessageThread *lm_lmx_message_thread, const char *registry_path, int required, int *out_loaded) {
    (void)lm_lmx_message_thread;
    return lm_trans_registry_load_file_path_mode(lm_lmx_message_thread, registry_path, required, 0, out_loaded);
}

static int lm_trans_registry_load_bootstrap_file_path(struct LmMessageThread *lm_lmx_message_thread, const char *registry_path, int required, int *out_loaded) {
    (void)lm_lmx_message_thread;
    return lm_trans_registry_load_file_path_mode(lm_lmx_message_thread, registry_path, required, 1, out_loaded);
}

static int lm_trans_registry_candidate_path(struct LmMessageThread *lm_lmx_message_thread, const char *source_path, const char *candidate_name, char *registry_path, size_t registry_path_size) {
    (void)lm_lmx_message_thread;
    if (candidate_name == 0 || registry_path == 0 || registry_path_size == 0U) {
        return 1;
    }
    if (strncmp(candidate_name, "lm2/", 4U) == 0) {
        return lm_trans_registry_project_path_for_source(lm_lmx_message_thread, source_path, candidate_name, registry_path, registry_path_size);
    }
    return lm_trans_registry_path_for_source(lm_lmx_message_thread, source_path, candidate_name, registry_path, registry_path_size);
}

static const char * lm_trans_registry_core_candidate_name(struct LmMessageThread *lm_lmx_message_thread, size_t index) {
    (void)lm_lmx_message_thread;
    if (index == 0U) {
        return "lm2/core.lm2";
    }
    if (index == 1U) {
        return "core.lm2";
    }
    return 0;
}

static const char * lm_trans_registry_primitive_candidate_name(struct LmMessageThread *lm_lmx_message_thread, size_t index) {
    (void)lm_lmx_message_thread;
    if (index == 0U) {
        return "lm2/primitive.lm2";
    }
    if (index == 1U) {
        return "primitive.lm2";
    }
    return 0;
}

static const char * lm_trans_registry_convert_candidate_name(struct LmMessageThread *lm_lmx_message_thread, size_t index) {
    (void)lm_lmx_message_thread;
    if (index == 0U) {
        return "lm2/convert.lm2";
    }
    if (index == 1U) {
        return "convert.lm2";
    }
    return 0;
}

static const char * lm_trans_registry_candidate_name(struct LmMessageThread *lm_lmx_message_thread, size_t index) {
    (void)lm_lmx_message_thread;
    if (index == 0U) {
        return "lm2/trans_registry.lm2";
    }
    if (index == 1U) {
        return "trans_registry.lm2";
    }
    if (index == 2U) {
        return "trans_registry.lmx";
    }
    if (index == 3U) {
        return "lm2/trans_registry.lmx";
    }
    return 0;
}

static int lm_trans_registry_load_for_source(struct LmMessageThread *lm_lmx_message_thread, const char *source_path) {
    (void)lm_lmx_message_thread;
    char registry_path[4096];
    const char *candidate_name;
    const char *override_path;
    const char *view_mode;
    int override_enabled;
    int loaded;
    int registry_loaded;
    size_t candidate_index;
    lm_trans_registry_destroy(lm_lmx_message_thread);
    if (lm_trans_registry_init(lm_lmx_message_thread) != 0) {
        return 1;
    }
    lm_trans_registry->loaded = 1;
    view_mode = getenv("LM_TRANS_REGISTRY_VIEW");
    if (view_mode == 0 || view_mode[0] == '\0' || strcmp(view_mode, "0") == 0 || strcmp(view_mode, "legacy") == 0) {
        lm_trans_registry->view_mode = 0;
    }
    else {
        lm_trans_registry->view_mode = 1;
        if (strcmp(view_mode, "view") == 0) {
            lm_trans_registry->view_mode = 2;
        }
    }
    lm_trans_registry->identifiers = lm_trans_identifier_table_new(lm_lmx_message_thread);
    lm_trans_registry->value_arena = lm_own_new_zero(sizeof(lm_trans_registry -> value_arena[0]));
    lm_trans_registry->loaded_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_registry->predefined_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_registry->predefined_descriptor_sites = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_registry->early_l2_source_sites = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    if (lm_trans_registry -> identifiers == 0 || lm_trans_registry -> value_arena == 0 || lm_own_arena_init(lm_lmx_message_thread, lm_trans_registry -> value_arena, lm_lmx_message_thread) != 0 || lm_trans_registry -> loaded_paths == 0 || lm_trans_registry -> predefined_paths == 0 || lm_trans_registry -> predefined_descriptor_sites == 0 || lm_trans_registry -> early_l2_source_sites == 0) {
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    lm_trans_registry->source_path = lm_trans_text_copy_cstr_from_cstr(lm_lmx_message_thread, source_path);
    if (lm_trans_registry -> source_path == 0) {
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    lm_trans_registry->loaded_fact_count = 0U;
    if (lm_trans_l4_payload_pointer_bindings_init(lm_lmx_message_thread) != 0) {
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    candidate_index = 0U;
    candidate_name = lm_trans_registry_core_candidate_name(lm_lmx_message_thread, candidate_index);
    while (candidate_name != 0) {
        if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (lm_trans_registry_load_bootstrap_file_path(lm_lmx_message_thread, registry_path, 0, &loaded) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (loaded != 0) {
            break;
        }
        candidate_index = candidate_index + 1U;
        candidate_name = lm_trans_registry_core_candidate_name(lm_lmx_message_thread, candidate_index);
    }
    loaded = 0;
    candidate_index = 0U;
    candidate_name = lm_trans_registry_primitive_candidate_name(lm_lmx_message_thread, candidate_index);
    while (candidate_name != 0) {
        if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (lm_trans_registry_load_bootstrap_file_path(lm_lmx_message_thread, registry_path, 0, &loaded) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (loaded != 0) {
            break;
        }
        candidate_index = candidate_index + 1U;
        candidate_name = lm_trans_registry_primitive_candidate_name(lm_lmx_message_thread, candidate_index);
    }
    if (loaded == 0) {
        fprintf(stderr, "trans registry error: cannot read lm2/primitive.lm2 or primitive.lm2\n");
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    loaded = 0;
    candidate_index = 0U;
    candidate_name = lm_trans_registry_convert_candidate_name(lm_lmx_message_thread, candidate_index);
    while (candidate_name != 0) {
        if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (lm_trans_registry_load_bootstrap_file_path(lm_lmx_message_thread, registry_path, 0, &loaded) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (loaded != 0) {
            break;
        }
        candidate_index = candidate_index + 1U;
        candidate_name = lm_trans_registry_convert_candidate_name(lm_lmx_message_thread, candidate_index);
    }
    if (loaded == 0) {
        fprintf(stderr, "trans registry error: cannot read lm2/convert.lm2 or convert.lm2\n");
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    override_path = getenv("LM_TRANS_REGISTRY");
    override_enabled = override_path != 0 && override_path[0] != '\0';
    registry_loaded = 0;
    if (override_enabled != 0) {
        if (strlen(override_path) >= 4096U) {
            fprintf(stderr, "trans error: LM_TRANS_REGISTRY path is too long\n");
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        strcpy(registry_path, override_path);
        if (lm_trans_registry_load_bootstrap_file_path(lm_lmx_message_thread, registry_path, 1, &loaded) != 0) {
            lm_trans_registry_destroy(lm_lmx_message_thread);
            return 1;
        }
        if (loaded != 0) {
            registry_loaded = 1;
        }
    }
    else {
        candidate_index = 0U;
        candidate_name = lm_trans_registry_candidate_name(lm_lmx_message_thread, candidate_index);
        while (candidate_name != 0) {
            if (lm_trans_registry_candidate_path(lm_lmx_message_thread, source_path, candidate_name, registry_path, 4096U) != 0) {
                lm_trans_registry_destroy(lm_lmx_message_thread);
                return 1;
            }
            if (lm_trans_registry_load_bootstrap_file_path(lm_lmx_message_thread, registry_path, 0, &loaded) != 0) {
                lm_trans_registry_destroy(lm_lmx_message_thread);
                return 1;
            }
            if (loaded != 0) {
                registry_loaded = 1;
                break;
            }
            candidate_index = candidate_index + 1U;
            candidate_name = lm_trans_registry_candidate_name(lm_lmx_message_thread, candidate_index);
        }
    }
    if (registry_loaded == 0) {
        fprintf(stderr, "trans registry error: cannot read trans_registry.lm2 or trans_registry.lmx\n");
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    if (lm_trans_registry_assert_view_parity(lm_lmx_message_thread) != 0) {
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    return 0;
}

static int lm_trans_emit_module_prelude_plan(struct LmMessageThread *lm_lmx_message_thread, FILE *file) {
    (void)lm_lmx_message_thread;
    LmTransNamespace * namespace_;
    int emitted;
    int status;
    namespace_ = lm_trans_namespace_new(lm_lmx_message_thread);
    if (namespace_ == 0) {
        return 1;
    }
    emitted = 0;
    status = lm_trans_namespace_attach_registry(lm_lmx_message_thread, namespace_);
    if (status == 0) {
        status = lm_trans_emit_core_include_table(lm_lmx_message_thread, file, namespace_, &emitted);
    }
    if (status == 0) {
        status = lm_trans_emit_configured_prelude_sequences(lm_lmx_message_thread, file, namespace_, &emitted);
    }
    if (status == 0 && emitted != 0) {
        status = lm_trans_put(lm_lmx_message_thread, file, "\n");
    }
    lm_trans_namespace_delete(lm_lmx_message_thread, namespace_);
    return status;
}

static int lm_trans_emit_document(struct LmMessageThread *lm_lmx_message_thread, const char *source_path, const char *output_path) {
    (void)lm_lmx_message_thread;
    LmP0Document * document;
    const LmP0Diagnostic * diagnostic;
    const LmP0Node * root;
    FILE * output;
    FILE * prelude_output;
    FILE * body_output;
    FILE * previous_prelude_output;
    char *prelude_path;
    char *body_path;
    int status;
    int close_status;
    int projection_status;
    int emitted;
    int typedef_projection_entered;
    int previous_conditional_emission_depth;
    document = 0;
    output = 0;
    prelude_output = 0;
    body_output = 0;
    previous_prelude_output = lm_trans_prelude_output;
    previous_conditional_emission_depth = lm_trans_l2_conditional_emission_depth;
    prelude_path = 0;
    body_path = 0;
    typedef_projection_entered = 0;
    if (lm_trans_path_has_extension(lm_lmx_message_thread, source_path, ".lm4") != 0) {
        fprintf(stderr, "trans error: .lm4 source modules are not supported: %s\n", source_path);
        return 1;
    }
    if (lm_trans_registry_load_for_source(lm_lmx_message_thread, source_path) != 0) {
        return 1;
    }
    status = lm_p0_parse_file(lm_lmx_message_thread, source_path, &document);
    if (status != 0) {
        diagnostic = lm_p0_document_diagnostic(lm_lmx_message_thread, document);
        if (diagnostic != 0) {
            fprintf(stderr, "trans parse error %d at %zu:%zu: %s\n", diagnostic -> code, diagnostic -> line, diagnostic -> column, diagnostic -> message);
        }
        else {
            fprintf(stderr, "trans parse error while reading %s\n", source_path);
        }
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    root = lm_p0_document_root(lm_lmx_message_thread, document);
    if (lm_trans_registry_load_inline_root(lm_lmx_message_thread, root, source_path) != 0 || lm_trans_materialize_local_l2_source_root(lm_lmx_message_thread, root, source_path, lm_trans_path_has_extension(lm_lmx_message_thread, source_path, ".lm2")) != 0 || lm_trans_registry_assert_view_parity(lm_lmx_message_thread) != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    prelude_path = lm_trans_temp_output_path_new(lm_lmx_message_thread, output_path, ".prelude.tmp");
    body_path = lm_trans_temp_output_path_new(lm_lmx_message_thread, output_path, ".body.tmp");
    if (prelude_path == 0 || body_path == 0) {
        fprintf(stderr, "trans error: cannot allocate temporary output paths\n");
        lm_own_delete(prelude_path, 0);
        lm_own_delete(body_path, 0);
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    prelude_output = fopen(prelude_path, "w+b");
    body_output = fopen(body_path, "w+b");
    if (prelude_output == 0 || body_output == 0) {
        fprintf(stderr, "trans error: cannot create temporary output streams\n");
        if (prelude_output != 0) {
            fclose(prelude_output);
        }
        if (body_output != 0) {
            fclose(body_output);
        }
        remove(prelude_path);
        remove(body_path);
        lm_own_delete(prelude_path, 0);
        lm_own_delete(body_path, 0);
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    lm_trans_prelude_output = prelude_output;
    lm_trans_current_source_path = source_path;
    lm_trans_module_init_root_source_path = source_path;
    lm_trans_module_init_root_main_count = 0U;
    lm_trans_module_init_wrapped_main_seen = 0;
    lm_trans_next_array_value_helper_id = 0U;
    lm_trans_next_anonymous_structure_id = 0U;
    lm_trans_emitted_message_thread_runtime_prelude = 0;
    lm_trans_emitted_message_thread_main_helper = 0;
    lm_trans_emitted_message_thread_assert_helper = 0;
    lm_trans_emitted_c_calling_convention_prelude = 0;
    lm_trans_emitted_structure_graph_header = 0;
    lm_trans_l2_table_materialization_suppression_depth = 0;
    lm_trans_l2_conditional_import_depth = 0;
    lm_trans_l2_executable_statement_depth = 0;
    lm_trans_l2_conditional_emission_depth = 0;
    lm_trans_module_init_unsupported_wrapper_depth = 0;
    emitted = 0;
    status = 0;
    if (lm_trans_typedef_projection_output_enter(lm_lmx_message_thread, prelude_output, body_output) != 0) {
        fprintf(stderr, "trans error: out of memory while creating typedef projection state\n");
        status = 1;
    }
    else {
        typedef_projection_entered = 1;
    }
    lm_trans_declared_import_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_declared_import_documents = lm_trans_ptr_stack_new(lm_lmx_message_thread, 0);
    lm_trans_emitted_import_prelude_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_import_module_init_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_import_function_paths = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_callable_adapters = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_callable_binders = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_array_value_helpers = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    lm_trans_emitted_function_return_structs = lm_trans_ptr_stack_new(lm_lmx_message_thread, lm_own_delete_plain);
    if (lm_trans_declared_import_paths == 0 || lm_trans_declared_import_documents == 0 || lm_trans_emitted_import_prelude_paths == 0 || lm_trans_emitted_import_module_init_paths == 0 || lm_trans_emitted_import_function_paths == 0 || lm_trans_emitted_callable_adapters == 0 || lm_trans_emitted_callable_binders == 0 || lm_trans_emitted_array_value_helpers == 0 || lm_trans_emitted_function_return_structs == 0 || lm_trans_module_init_registry_init(lm_lmx_message_thread) != 0) {
        fprintf(stderr, "trans error: out of memory while creating module state stacks\n");
        status = 1;
    }
    if (status == 0 && (lm_trans_typedef_projection_reserve_loaded_source_paths(lm_lmx_message_thread) != 0 || lm_trans_typedef_projection_reserve_source_node(lm_lmx_message_thread, root) != 0 || lm_trans_module_init_names_prepare(lm_lmx_message_thread) != 0)) {
        status = 1;
    }
    if (status == 0) {
        status = lm_trans_emit_module_prelude_plan(lm_lmx_message_thread, prelude_output);
    }
    if (status == 0) {
        status = lm_trans_emit_root_sequence(lm_lmx_message_thread, body_output, root, lm_trans_path_has_extension(lm_lmx_message_thread, source_path, ".lm2"), &emitted);
    }
    if (status == 0 && lm_trans_module_init_entry_count(lm_lmx_message_thread) != 0U && lm_trans_module_init_wrapped_main_seen) {
        fprintf(stderr, "trans hosted module-init limitation: a conditional or wrapped main cannot host module value initialization\n");
        status = 1;
    }
    if (status == 0 && lm_trans_module_init_entry_count(lm_lmx_message_thread) != 0U && lm_trans_module_init_root_main_count == 0U) {
        fprintf(stderr, "trans hosted module-init limitation: top-level aggregate values require one root external main\n");
        status = 1;
    }
    if (status == 0 && lm_trans_module_init_root_main_count != 0U) {
        status = lm_trans_emit_module_init_dispatcher(lm_lmx_message_thread, prelude_output);
    }
    lm_trans_module_init_registry_destroy(lm_lmx_message_thread);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_function_return_structs);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_array_value_helpers);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_callable_binders);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_callable_adapters);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_import_function_paths);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_import_module_init_paths);
    lm_trans_ptr_stack_delete(&lm_trans_emitted_import_prelude_paths);
    lm_trans_import_documents_drain(lm_lmx_message_thread, lm_trans_declared_import_documents);
    lm_trans_ptr_stack_delete(&lm_trans_declared_import_documents);
    lm_trans_ptr_stack_delete(&lm_trans_declared_import_paths);
    projection_status = 0;
    if (typedef_projection_entered) {
        projection_status = lm_trans_typedef_projection_output_leave(lm_lmx_message_thread);
    }
    if (projection_status != 0) {
        fprintf(stderr, "trans error: unbalanced typedef projection state\n");
        status = 1;
    }
    lm_trans_l2_table_materialization_suppression_depth = 0;
    lm_trans_l2_conditional_import_depth = 0;
    lm_trans_l2_executable_statement_depth = 0;
    lm_trans_l2_conditional_emission_depth = previous_conditional_emission_depth;
    lm_trans_module_init_unsupported_wrapper_depth = 0;
    lm_trans_module_init_root_main_count = 0U;
    lm_trans_module_init_wrapped_main_seen = 0;
    lm_trans_module_init_root_source_path = 0;
    lm_trans_current_source_path = 0;
    lm_trans_prelude_output = previous_prelude_output;
    if (status == 0 && emitted == 0) {
        fprintf(stderr, "trans error: root L1 or L2 frame was not found\n");
        status = 1;
    }
    if (status == 0) {
        output = fopen(output_path, "wb");
        if (output == 0) {
            fprintf(stderr, "trans error: cannot open output file %s\n", output_path);
            status = 1;
        }
    }
    if (status == 0 && (lm_trans_copy_stream(lm_lmx_message_thread, output, prelude_output) != 0 || lm_trans_copy_stream(lm_lmx_message_thread, output, body_output) != 0)) {
        fprintf(stderr, "trans error: cannot write output file %s\n", output_path);
        status = 1;
    }
    close_status = 0;
    if (output != 0) {
        close_status = fclose(output);
    }
    fclose(prelude_output);
    fclose(body_output);
    remove(prelude_path);
    remove(body_path);
    lm_own_delete(prelude_path, 0);
    lm_own_delete(body_path, 0);
    if (status != 0) {
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    if (close_status != 0) {
        fprintf(stderr, "trans error: cannot write output file %s\n", output_path);
        lm_p0_document_destroy(lm_lmx_message_thread, document);
        lm_trans_registry_destroy(lm_lmx_message_thread);
        return 1;
    }
    lm_p0_document_destroy(lm_lmx_message_thread, document);
    lm_trans_registry_destroy(lm_lmx_message_thread);
    return 0;
}


static FILE * lm_trans_tmpfile(struct LmMessageThread *lm_lmx_message_thread) {
    (void)lm_lmx_message_thread;
    FILE * file;
    char *dir;
    char path[512];
    char *format;
    file = tmpfile();
    if (file != 0) {
        return file;
    }
    dir = getenv("TEMP");
    if (dir == 0 || dir[0] == '\0') {
        dir = getenv("TMP");
    }
    if (dir == 0 || dir[0] == '\0') {
        dir = getenv("TMPDIR");
    }
    if (dir == 0 || dir[0] == '\0') {
        fprintf(stderr, "trans error: cannot create a temporary file\n");
        return 0;
    }
    format = "%s/lmx-%p-%zu.tmp";
    if (strchr(dir, '\\') != 0) {
        format = "%s\\lmx-%p-%zu.tmp";
    }
    lm_trans_tmpfile_seq = lm_trans_tmpfile_seq + 1U;
    if (snprintf(path, 512, format, dir, &path, lm_trans_tmpfile_seq) < 0) {
        fprintf(stderr, "trans error: cannot create a temporary file\n");
        return 0;
    }
    file = fopen(path, "w+bDx");
    if (file != 0) {
        return file;
    }
    file = fopen(path, "w+bx");
    if (file != 0) {
        return file;
    }
    file = fopen(path, "w+bD");
    if (file != 0) {
        return file;
    }
    file = fopen(path, "w+b");
    if (file == 0) {
        fprintf(stderr, "trans error: cannot create a temporary file\n");
    }
    return file;
}

