static int lm_trans_identifier_payload(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *atom, LmP0Text *out_payload) {
    (void)lm_lmx_message_thread;
    if (atom == 0 || out_payload == 0 || atom -> data == 0) {
        return 0;
    }
    out_payload->data = atom -> data;
    out_payload->length = atom -> length;
    if (atom -> length >= 2U && atom -> data[0] == '`' && atom -> data[atom -> length - 1U] == '`') {
        out_payload->data = atom -> data + 1U;
        out_payload->length = atom -> length - 2U;
    }
    return 1;
}

static int lm_trans_identifier_same(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *left, const LmP0Text *right) {
    (void)lm_lmx_message_thread;
    LmP0Text * left_payload;
    LmP0Text * right_payload;
    int same;
    left_payload = lm_trans_text_ref_new_cstr("");
    right_payload = lm_trans_text_ref_new_cstr("");
    if (left_payload == 0 || right_payload == 0) {
        lm_trans_text_ref_destroy(&left_payload);
        lm_trans_text_ref_destroy(&right_payload);
        return 0;
    }
    if (lm_trans_identifier_payload(lm_lmx_message_thread, left, left_payload) == 0 || lm_trans_identifier_payload(lm_lmx_message_thread, right, right_payload) == 0) {
        lm_trans_text_ref_destroy(&left_payload);
        lm_trans_text_ref_destroy(&right_payload);
        return 0;
    }
    same = lm_trans_text_same(lm_lmx_message_thread, left_payload, right_payload);
    lm_trans_text_ref_destroy(&left_payload);
    lm_trans_text_ref_destroy(&right_payload);
    return same;
}

static int lm_trans_emit_identifier(struct LmMessageThread *lm_lmx_message_thread, FILE *file, const LmP0Text *name) {
    (void)lm_lmx_message_thread;
    LmP0Text * payload;
    int status;
    payload = lm_trans_text_ref_new_cstr("");
    if (payload == 0) {
        return 1;
    }
    if (lm_trans_identifier_payload(lm_lmx_message_thread, name, payload) == 0) {
        lm_trans_text_ref_destroy(&payload);
        return 1;
    }
    status = lm_trans_write_text(lm_lmx_message_thread, file, payload);
    lm_trans_text_ref_destroy(&payload);
    return status;
}

static int lm_trans_registry_identifier_value(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *atom, LmP0Text *out_payload) {
    (void)lm_lmx_message_thread;
    if (atom == 0 || out_payload == 0) {
        return 0;
    }
    if (atom -> length > 0U && (atom -> data[0] == '"' || atom -> data[0] == '\'')) {
        return 0;
    }
    return lm_trans_identifier_payload(lm_lmx_message_thread, atom, out_payload);
}

static int lm_trans_registry_literal_value(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *atom, LmP0Text *out_payload) {
    (void)lm_lmx_message_thread;
    char quote;
    if (atom == 0 || out_payload == 0 || atom -> data == 0) {
        return 0;
    }
    out_payload->data = atom -> data;
    out_payload->length = atom -> length;
    if (atom -> length < 2U) {
        return 1;
    }
    quote = atom -> data[0];
    if ((quote == '"' || quote == '\'') && atom -> data[atom -> length - 1U] == quote) {
        out_payload->data = atom -> data + 1U;
        out_payload->length = atom -> length - 2U;
        return 1;
    }
    return lm_trans_identifier_payload(lm_lmx_message_thread, atom, out_payload);
}

static int lm_trans_registry_payload_is_null(struct LmMessageThread *lm_lmx_message_thread, const LmP0Text *atom) {
    (void)lm_lmx_message_thread;
    LmP0Text * payload;
    int is_null;
    payload = lm_trans_text_ref_new_cstr("");
    if (payload == 0) {
        return 0;
    }
    if (lm_trans_registry_identifier_value(lm_lmx_message_thread, atom, payload) == 0) {
        lm_trans_text_ref_destroy(&payload);
        return 0;
    }
    is_null = payload -> length == 4U && memcmp(payload -> data, "None", 4U) == 0;
    lm_trans_text_ref_destroy(&payload);
    return is_null;
}

